<template>
  <button 
    class="menu-button" 
    @click="toggleDrawer"
    aria-label="Open menu"
    aria-expanded="false"
  >
    <span class="menu-icon">☰</span>
  </button>
</template>

<script>
import { mapActions } from 'vuex'

export default {
  name: 'MenuButton',
  methods: {
    ...mapActions('drawer', ['toggleDrawer'])
  }
}
</script>

<style scoped>
.menu-button {
  background: transparent;
  border: none;
  border-radius: 0;
  width: 40px;
  height: 40px;
  min-width: 40px;
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.15s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.menu-button::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.3s cubic-bezier(0.4, 0.0, 0.2, 1), 
              height 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.menu-button:active::before {
  width: 100%;
  height: 100%;
}

.menu-icon {
  color: white;
  font-size: 30px;
  font-weight: 400;
  line-height: 1;
  position: relative;
  z-index: 1;
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}
</style>
