<template>
  <div class="tracking-container">
    <div class="tracking-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>Order Tracking</h1>
        <p v-if="trackingData">Collection Code #{{ trackingData.id }}</p>
      </div>
    </div>
    
    <div v-if="loading" class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading order details...</p>
    </div>
    
    <div v-else-if="error" class="error-container">
      <div class="error-icon">⚠</div>
      <p class="error-text">{{ errorMessage }}</p>
      <button @click="loadTrackingData" class="retry-button">Try Again</button>
    </div>
    
    <div v-else-if="trackingData" class="tracking-content">
      <!-- Status Card -->
      <div class="status-card">
        <div class="status-header">
          <h2>Order Status</h2>
          <span class="status-badge" :class="statusClass">{{ formattedStatus }}</span>
        </div>
      </div>
      
      <!-- Driver Information -->
      <div v-if="trackingData.driver" class="driver-card">
        <div class="card-header">
          <h3>Your Driver</h3>
          <span class="transport-badge">{{ getTransportIcon(trackingData.driver.transport_type) }} {{ formatTransportType(trackingData.driver.transport_type) }}</span>
        </div>
        <div class="driver-info">
          <div class="driver-avatar">
            <span>{{ getInitials(trackingData.driver.display_name) }}</span>
          </div>
          <div class="driver-details">
            <h4>{{ trackingData.driver.display_name }}</h4>
            <a v-if="trackingData.driver.phone" @click="callDriver(trackingData.driver.phone)" class="driver-phone">
              📞 {{ trackingData.driver.phone }}
            </a>

            <a v-if="!trackingData.driver.phone" class="driver-phone">
              📞 {{ trackingData.driver.phone }}
            </a>

          </div>
        </div>
      </div>
      
      <!-- Delivery Timeline -->
      <div v-if="trackingData.deliveries && trackingData.deliveries.length > 0" class="timeline-card">
        <h3>Delivery Timeline</h3>
        <div class="timeline">
          <div class="timeline-item">
            <div class="timeline-marker pickup"></div>
            <div class="timeline-content">
              <h4>Pickup</h4>
              <p class="timeline-time">{{ formatDateTime(trackingData.deliveries[0].eta.pickup) }}</p>
            </div>
          </div>
          <div class="timeline-line"></div>
          <div class="timeline-item">
            <div class="timeline-marker dropoff"></div>
            <div class="timeline-content">
              <h4>Estimated Delivery</h4>
              <p class="timeline-time">{{ formatDateTime(trackingData.deliveries[0].eta.dropoff) }}</p>
            </div>
          </div>
        </div>
      </div>
      
      <!-- Map Location (if coordinates available) -->

    </div>
  </div>
</template>

<script>
import { mapActions } from 'vuex'
import { showAlert, makePhoneCall } from '@/utils/webUtils'

export default {
  name: 'OrderTracking',
  data() {
    return {
      trackingData: null,
      loading: false,
      error: false,
      errorMessage: '',
      pollingInterval: null
    }
  },
  computed: {
    orderId() {
      return this.$route.params.orderId
    },
    formattedStatus() {
      if (!this.trackingData) return ''
      return this.trackingData.status
        .split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join(' ')
    },
    statusClass() {
      if (!this.trackingData) return ''
      const status = this.trackingData.status.toLowerCase()
      if (status === 'in_progress') return 'status-in-progress'
      if (status === 'completed') return 'status-completed'
      if (status === 'cancelled') return 'status-cancelled'
      return 'status-pending'
    }
  },
  mounted() {
    this.loadTrackingData()
    this.startPolling()
  },
  beforeDestroy() {
    this.stopPolling()
  },
  watch: {
    '$route.params.orderId'(newId) {
      if (newId) {
        this.stopPolling()
        this.loadTrackingData()
        this.startPolling()
      }
    }
  },
  methods: {
    ...mapActions('auth', ['fetchOrderTracking']),
    async loadTrackingData(isPolling = false) {
      if (!this.orderId) {
        this.error = true
        this.errorMessage = 'Order ID not found'
        return
      }
      
      // Only show loading spinner on initial load, not during polling
      if (!isPolling) {
        this.loading = true
        this.error = false
        this.errorMessage = ''
      }
      
      console.log(`[Order Tracking] ${isPolling ? 'Polling' : 'Initial'} request to /auth/client/tracking/${this.orderId}`)
      
      try {
        this.trackingData = await this.fetchOrderTracking(this.orderId)
        console.log('[Order Tracking] Data received:', this.trackingData)
        // Clear error state on successful update
        this.error = false
        this.errorMessage = ''
      } catch (error) {
        console.error('[Order Tracking] Error:', error)
        // Only set error state on initial load, not during polling
        if (!isPolling) {
          this.error = true
          this.errorMessage = error.response?.data?.message || 
                            error.message || 
                            'Failed to load order tracking. Please try again.'
        }
        // Only show alert on initial load, not on polling updates
        if (!isPolling) {
          showAlert('Load Tracking Failed', this.errorMessage)
        }
      } finally {
        if (!isPolling) {
          this.loading = false
        }
      }
    },
    callDriver(number){
      makePhoneCall(number);
    },
    startPolling() {
      // Clear any existing interval
      this.stopPolling()
      // Set up polling every 30 seconds
      // 30 seconds = 30000 milliseconds
      const POLLING_INTERVAL = 30 * 1000 // 30 seconds in milliseconds
      console.log('Starting polling for order tracking - will update every 30 seconds')
      this.pollingInterval = setInterval(() => {
        console.log('Polling: Fetching order tracking data...', new Date().toLocaleTimeString())
        // Pass true to indicate this is a polling update
        this.loadTrackingData(true)
      }, POLLING_INTERVAL)
    },
    stopPolling() {
      if (this.pollingInterval) {
        clearInterval(this.pollingInterval)
        this.pollingInterval = null
      }
    },
    goBack() {
      this.$router.go(-1)
    },
    formatDateTime(dateString) {
      if (!dateString) return 'N/A'
      const date = new Date(dateString)
      return date.toLocaleString('en-US', {
        weekday: 'short',
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        hour12: true
      })
    },
    getInitials(name) {
      if (!name) return '?'
      const parts = name.split(' ')
      if (parts.length >= 2) {
        return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
      }
      return name.substring(0, 2).toUpperCase()
    },
    formatTransportType(type) {
      if (!type) return 'Vehicle'
      return type.charAt(0).toUpperCase() + type.slice(1)
    },
    getTransportIcon(type) {
      const icons = {
        bike: '🚴',
        car: '🚗',
        scooter: '🛵',
        walk: '🚶'
      }
      return icons[type] || '🚗'
    }
  }
}
</script>

