// Web utility functions to replace Android-specific functions

/**
 * Extract error message from axios error response
 * Handles various error response formats from the server
 * @param {Error} error - Axios error object
 * @param {string} defaultMessage - Default message if error cannot be extracted
 * @returns {string} - Error message
 */
export function getErrorMessage(error, defaultMessage = 'An error occurred. Please try again.') {
  if (!error) {
    return defaultMessage
  }

  // If error.response exists, try to extract message from response data
  if (error.response?.data) {
    const data = error.response.data
    
    // If data is a string, return it directly
    if (typeof data === 'string') {
      return data
    }
    
    // If data has a message property
    if (data.message) {
      return data.message
    }
    
    // If data has an error property
    if (data.error) {
      return typeof data.error === 'string' ? data.error : data.error.message || defaultMessage
    }
    
    // If data itself is an object, try to stringify meaningful fields
    if (typeof data === 'object') {
      // Check for common error message fields
      const messageFields = ['msg', 'errorMessage', 'error_msg', 'detail', 'description']
      for (const field of messageFields) {
        if (data[field]) {
          return data[field]
        }
      }
    }
  }

  // Fall back to error.message if available
  if (error.message) {
    // Don't show generic axios messages like "Request failed with status code 404"
    if (error.message.includes('status code') && error.response?.data) {
      // Try to get the actual error from response data
      const data = error.response.data
      if (typeof data === 'string') return data
      if (data.message) return data.message
      if (data.error) return typeof data.error === 'string' ? data.error : data.error.message || defaultMessage
    }
    return error.message
  }

  return defaultMessage
}

/**
 * Show an alert dialog (replaces Android.showAlert)
 * @param {string} title - Alert title
 * @param {string} message - Alert message
 */
export function showAlert(title, message) {
  window.alert(`${title}\n\n${message}`)
}

/**
 * Show a toast notification (replaces Android.showToast)
 * @param {string} message - Toast message
 * @param {number} duration - Duration in milliseconds (default: 3000)
 */
export function showToast(message, duration = 3000) {
  // Remove existing toast if any
  const existingToast = document.getElementById('web-toast')
  if (existingToast) {
    existingToast.remove()
  }

  // Create toast element
  const toast = document.createElement('div')
  toast.id = 'web-toast'
  toast.textContent = message
  toast.style.cssText = `
    position: fixed;
    bottom: 20px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(0, 0, 0, 0.87);
    color: #FFFFFF;
    padding: 12px 24px;
    border-radius: 4px;
    font-size: 14px;
    font-family: 'Roboto', sans-serif;
    z-index: 10000;
    box-shadow: 0px 3px 5px -1px rgba(0, 0, 0, 0.2), 0px 6px 10px 0px rgba(0, 0, 0, 0.14), 0px 1px 18px 0px rgba(0, 0, 0, 0.12);
    animation: toastSlideIn 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
    pointer-events: none;
  `

  // Add animation keyframes if not already added
  if (!document.getElementById('toast-styles')) {
    const style = document.createElement('style')
    style.id = 'toast-styles'
    style.textContent = `
      @keyframes toastSlideIn {
        from {
          opacity: 0;
          transform: translateX(-50%) translateY(20px);
        }
        to {
          opacity: 1;
          transform: translateX(-50%) translateY(0);
        }
      }
      @keyframes toastSlideOut {
        from {
          opacity: 1;
          transform: translateX(-50%) translateY(0);
        }
        to {
          opacity: 0;
          transform: translateX(-50%) translateY(20px);
        }
      }
    `
    document.head.appendChild(style)
  }

  document.body.appendChild(toast)

  // Remove toast after duration
  setTimeout(() => {
    toast.style.animation = 'toastSlideOut 0.3s cubic-bezier(0.4, 0.0, 0.2, 1)'
    setTimeout(() => {
      if (toast.parentNode) {
        toast.remove()
      }
    }, 300)
  }, duration)
}

/**
 * Vibrate device (replaces Android.vibrate)
 * @param {number|number[]} pattern - Vibration pattern in milliseconds
 */
export function vibrate(pattern) {
  if (navigator.vibrate) {
    // If pattern is a single number, convert to array
    const vibrationPattern = Array.isArray(pattern) ? pattern : [pattern]
    navigator.vibrate(vibrationPattern)
  }
}

/**
 * Show a confirmation dialog (replaces Android.showConfirmDialog)
 * @param {string} title - Dialog title
 * @param {string} message - Dialog message
 * @returns {boolean} - True if user confirmed, false otherwise
 */
export function showConfirmDialog(title, message) {
  return window.confirm(`${title}\n\n${message}`)
}

/**
 * Make a phone call (replaces Android.makePhoneCall)
 * @param {string} number - Phone number to call
 */
export function makePhoneCall(number) {
  window.location.href = `tel:${number}`
}
