const state = {
  isOpen: false
}

const mutations = {
  OPEN_DRAWER(state) {
    state.isOpen = true
  },
  CLOSE_DRAWER(state) {
    state.isOpen = false
  },
  TOGGLE_DRAWER(state) {
    state.isOpen = !state.isOpen
  }
}

const actions = {
  openDrawer({ commit }) {
    commit('OPEN_DRAWER')
  },
  closeDrawer({ commit }) {
    commit('CLOSE_DRAWER')
  },
  toggleDrawer({ commit }) {
    commit('TOGGLE_DRAWER')
  }
}

const getters = {
  isOpen: state => state.isOpen
}

export default {
  namespaced: true,
  state,
  mutations,
  actions,
  getters
}
