import api from '@/services/api'

const state = {
  items: JSON.parse(localStorage.getItem('cartItems') || '[]'),
  deliveryFee: 0
}

const mutations = {
  ADD_TO_CART(state, item) {
    const existingItem = state.items.find(i => i.id === item.id)
    if (existingItem) {
      existingItem.quantity += 1
    } else {
      state.items.push({
        ...item,
        quantity: 1
      })
    }
    localStorage.setItem('cartItems', JSON.stringify(state.items))
  },
  REMOVE_FROM_CART(state, itemId) {
    state.items = state.items.filter(item => item.id !== itemId)
    localStorage.setItem('cartItems', JSON.stringify(state.items))
  },
  UPDATE_QUANTITY(state, { itemId, quantity }) {
    const item = state.items.find(i => i.id === itemId)
    if (item) {
      if (quantity <= 0) {
        state.items = state.items.filter(i => i.id !== itemId)
      } else {
        item.quantity = quantity
      }
      localStorage.setItem('cartItems', JSON.stringify(state.items))
    }
  },
  CLEAR_CART(state) {
    state.items = []
    localStorage.removeItem('cartItems')
  },
  SET_DELIVERY_FEE(state, fee) {
    state.deliveryFee = fee
  }
}

const actions = {
  addToCart({ commit }, item) {
    commit('ADD_TO_CART', item)
  },
  removeFromCart({ commit }, itemId) {
    commit('REMOVE_FROM_CART', itemId)
  },
  updateQuantity({ commit }, payload) {
    commit('UPDATE_QUANTITY', payload)
  },
  clearCart({ commit }) {
    commit('CLEAR_CART')
  },
  async fetchDeliveryFee({ commit }) {
    try {
      const response = await api.get('/api/client/restaurant/price')
      commit('SET_DELIVERY_FEE', response.data.delivery_fee || 0)
      return response.data.delivery_fee || 0
    } catch (error) {
      console.error('Failed to fetch delivery fee:', error)
      commit('SET_DELIVERY_FEE', 0)
      return 0
    }
  }
}

const getters = {
  cartItems: state => state.items,
  cartItemCount: state => {
    return state.items.reduce((total, item) => total + item.quantity, 0)
  },
  cartSubtotal: state => {
    return state.items.reduce((total, item) => total + (item.price * item.quantity), 0)
  },
  deliveryFee: state => state.deliveryFee,
  serviceFee: () => 1.5, // Flat service fee
  cartTotal: state => {
    const subtotal = state.items.reduce((total, item) => total + (item.price * item.quantity), 0)
    return subtotal + state.deliveryFee + 1.5 // Subtotal + Delivery Fee + Service Fee
  }
}

export default {
  namespaced: true,
  state,
  mutations,
  actions,
  getters
}
