<template>
  <div class="payment-container">
    <div class="payment-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>Payment</h1>
        <p>Complete your order</p>
      </div>
    </div>
    
    <div v-if="loading" class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading payment form...</p>
    </div>
    
    <div v-else-if="error" class="error-container">
      <button @click="goBack" class="retry-button">Go Back</button>
    </div>
    
    <div v-else class="payment-content">
      <div class="payment-form-container">
        <div class="order-summary">
          <h2>Order Summary</h2>
          <div class="summary-item">
            <span>Order Price:</span>
            <span class="order-price">£{{ orderSubtotal.toFixed(2) }}</span>
          </div>
          <div class="summary-item">
            <span>Delivery Fee:</span>
            <span class="delivery-fee">£{{ deliveryFee.toFixed(2) }}</span>
          </div>
          <div class="summary-item">
            <span>Service Fee:</span>
            <span class="service-fee">£{{ serviceFee.toFixed(2) }}</span>
          </div>
          <div class="summary-item">
            <span>Total Amount:</span>
            <span class="total-amount">£{{ totalAmount.toFixed(2) }}</span>
          </div>
        </div>
        
        <div class="card-element-container">
          <label class="card-label">Card Details</label>
          <div id="card-element" class="card-element"></div>
          <div id="card-errors" class="card-errors" role="alert"></div>
          <div class="security-badge">
            <span class="lock-icon">🔒</span>
            <span class="security-text">Secured by</span>
            <span class="stripe-logo">Stripe</span>
          </div>
          <div class="accepted-cards">
            <p class="accepted-cards-label">We accept:</p>
            <div class="card-icons">
              <div class="card-icon visa" title="Visa">
                <div class="visa-logo">
                  <span class="visa-text">
                    <span class="visa-v">V</span>
                    <span class="visa-red-dot"></span>
                    <span class="visa-rest">ISA</span>
                  </span>
                </div>
                <span class="card-icon-text">Visa</span>
              </div>
              <div class="card-icon mastercard" title="Mastercard">
                <div class="mastercard-logo">
                  <div class="mastercard-circle mastercard-circle-left"></div>
                  <div class="mastercard-circle mastercard-circle-right"></div>
                </div>
                <span class="card-icon-text">mastercard</span>
              </div>
              <div class="card-icon discover" title="Discover">
                <div class="discover-logo">
                  <span class="discover-text">
                    <span class="discover-disc">DISC</span>
                    <span class="discover-o-circle"></span>
                    <span class="discover-red-dot"></span>
                    <span class="discover-ver">VER</span>
                  </span>
                  <div class="discover-curve"></div>
                </div>
                <span class="card-icon-text">Discover</span>
              </div>
            </div>
          </div>
        </div>
        
        <button 
          class="pay-button" 
          @click="handlePayment"
          :disabled="processing || !stripeLoaded"
        >
          <span v-if="processing">
            <span class="spinner-small"></span>
            Processing...
          </span>
          <span v-else>Pay £{{ totalAmount.toFixed(2) }}</span>
        </button>
        
        <div class="payment-footer">
          <p class="footer-text">
            <span class="footer-icon">🔐</span>
            Your payment information is encrypted and secure
          </p>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { loadStripe } from '@stripe/stripe-js'
import api from '@/services/api'
import { mapGetters } from 'vuex'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'Payment',
  computed: {
    ...mapGetters('cart', ['cartSubtotal', 'deliveryFee', 'serviceFee']),
    orderSubtotal() {
      return this.cartSubtotal || 0
    }
  },
  data() {
    return {
      stripe: null,
      elements: null,
      cardElement: null,
      clientSecret: null,
      orderId: null,
      totalAmount: 0,
      loading: true,
      processing: false,
      error: null,
      stripeLoaded: false
    }
  },
  async mounted() {
    // Get clientSecret and orderId from route query
    this.clientSecret = this.$route.query.clientSecret
    this.orderId = this.$route.query.orderId
    this.totalAmount = parseFloat(this.$route.query.totalAmount || 0)
    
    console.log('Payment page mounted:', {
      clientSecret: this.clientSecret ? 'Present' : 'Missing',
      orderId: this.orderId,
      totalAmount: this.totalAmount,
      query: this.$route.query
    })
    
    if (!this.clientSecret) {
      showAlert('Payment Error', 'Missing payment information. Please try again.')
      this.error = true
      this.loading = false
      return
    }
    
    try {
      // Initialize Stripe
      const stripeKey = 'pk_live_51QxvNBCSIhUsiiWS6FmmqAanXO8oJ4N7SbOMo5aKXEZ9mlQpvLKOXKXRupZrJavWH3vv3gQ5lRLxFvTrDji4nJIB00qIrUDWiZ'
      const stripe = await loadStripe(stripeKey)
      
      if (!stripe) {
        throw new Error('Failed to load Stripe')
      }
      
      this.stripe = stripe
      // Set locale to en-GB for UK-specific terminology (e.g., "Postcode" instead of "ZIP code")
      // This ensures UK postcodes like "M6 5WQ" are accepted
      this.elements = stripe.elements({
        locale: 'en-GB',
        appearance: {
          variables: {
            colorPrimary: '#C2410C'
          }
        }
      })
      
      // Set loading to false first so the DOM element is rendered
      this.loading = false
      
      // Wait for Vue to update the DOM before mounting Stripe element
      await this.$nextTick()
      
      // Verify the element exists before mounting
      const cardElementDom = document.getElementById('card-element')
      if (!cardElementDom) {
        throw new Error('Card element container not found in DOM')
      }
      
      // Create card element - hide postal code for UK (not required)
      this.cardElement = this.elements.create('card', {
        hidePostalCode: true,
        style: {
          base: {
            fontSize: '16px',
            color: 'rgba(0, 0, 0, 0.87)',
            fontFamily: 'Roboto, sans-serif',
            '::placeholder': {
              color: 'rgba(0, 0, 0, 0.38)',
            },
          },
          invalid: {
            color: '#BA1A1A',
            iconColor: '#BA1A1A',
          },
        },
      })
      
      // Mount the card element
      try {
        this.cardElement.mount('#card-element')
        console.log('Card element mounted successfully')
        
        // Handle real-time validation errors from the card Element
        this.cardElement.on('change', ({error}) => {
          if (error) {
            showAlert('Card Error', error.message)
          }
        })
        
        // Listen for ready event to ensure element is fully loaded
        this.cardElement.on('ready', () => {
          console.log('Card element is ready and interactive')
        })
        
        this.stripeLoaded = true
      } catch (mountError) {
        console.error('Error mounting card element:', mountError)
        throw mountError
      }
    } catch (err) {
      console.error('Error initializing Stripe:', err)
      console.error('Error details:', {
        message: err?.message,
        stack: err?.stack,
        clientSecret: this.clientSecret ? 'Present' : 'Missing',
        orderId: this.orderId,
        stripeKey: process.env.VUE_APP_STRIPE_PUBLISHABLE_KEY ? 'Present' : 'Missing',
        envKeys: Object.keys(process.env).filter(k => k.startsWith('VUE_APP_'))
      })
      
      // Show more specific error message
      const errorMessage = err?.message || err?.toString() || 'Unknown error'
      
      let alertMessage
      if (errorMessage.includes('Stripe publishable key') || errorMessage.includes('not configured')) {
        alertMessage = errorMessage + ' Please create a .env file in the project root with: VUE_APP_STRIPE_PUBLISHABLE_KEY=pk_test_your_key_here'
      } else {
        alertMessage = `Payment form error: ${errorMessage}. Please check the browser console for more details.`
      }
      showAlert('Payment Form Error', alertMessage)
      this.error = true
      this.loading = false
    }
  },
  beforeDestroy() {
    if (this.cardElement) {
      this.cardElement.unmount()
    }
  },
  methods: {
    goBack() {
      this.$router.go(-1)
    },
    async handlePayment() {
      if (!this.stripe || !this.cardElement) {
        showAlert('Payment Error', 'Payment form not ready. Please refresh the page.')
        return
      }
      
      this.processing = true
      this.error = null
      
      try {
        // Confirm payment with Stripe
        const { error, paymentIntent } = await this.stripe.confirmCardPayment(this.clientSecret, {
          payment_method: {
            card: this.cardElement,
          }
        })
        
        if (error) {
          // Show error to customer
          showAlert('Payment Failed', error.message)
          this.processing = false
        } else if (paymentIntent && paymentIntent.status === 'succeeded') {
          // Payment succeeded - clear cart and selected restaurant from storage
          this.$store.dispatch('cart/clearCart')
          // Clear selected restaurant from localStorage
          localStorage.removeItem('selectedRestaurant')
          
          // Use replace instead of push to prevent back navigation to payment page
          this.$router.replace({
            name: 'PaymentSuccess',
            params: {
              orderId: this.orderId
            }
          })
        }
      } catch (err) {
        console.error('Payment error:', err)
        showAlert('Payment Error', 'An error occurred during payment. Please try again.')
        this.processing = false
      }
    }
  }
}
</script>

