<template>
  <div class="login-container">
    <div class="login-card">
      <form @submit.prevent="isLoginMode ? handleLogin() : handleRegister()" class="login-form">
        <div class="welcome-header">
          <h2 v-if="isLoginMode">Welcome back 👋</h2>
          <h2 v-else>Create your account 🎉</h2>
          <p v-if="isLoginMode" class="welcome-subtitle">Sign in to continue</p>
        </div>
        
        <div v-if="!isLoginMode" class="form-group">
          <label for="firstName">First Name</label>
          <input
            id="firstName"
            v-model="form.firstName"
            type="text"
            placeholder="Enter your first name"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>

        <div v-if="!isLoginMode" class="form-group">
          <label for="lastName">Last Name</label>
          <input
            id="lastName"
            v-model="form.lastName"
            type="text"
            placeholder="Enter your last name"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        <div class="form-group">
          <label for="email">Email Address</label>
          <input
            id="email"
            v-model="form.email"
            type="email"
            placeholder="Enter your email"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        <div class="form-group">
          <label for="password">Password</label>
          <input
            id="password"
            v-model="form.password"
            type="password"
            placeholder="Enter your password"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        <div v-if="isLoginMode" class="forgot-password-container">
          <router-link to="/forgot-password" class="forgot-password-link">Forgot Password?</router-link>
        </div>
        
        <button
          type="submit"
          :disabled="loading"
          class="login-button"
        >
          <span v-if="loading">
            <span v-if="isLoginMode">Logging in...</span>
            <span v-else>Registering...</span>
          </span>
          <span v-else>
            <span v-if="isLoginMode">Login</span>
            <span v-else>Register</span>
          </span>
        </button>
        
        <div class="auth-toggle">
          <span v-if="isLoginMode">Don't have an account? </span>
          <span v-else>Already have an account? </span>
          <button
            type="button"
            class="toggle-link"
            @click="toggleMode"
            :disabled="loading"
          >
            <span v-if="isLoginMode">Register</span>
            <span v-else>Login</span>
          </button>
        </div>
      </form>
    </div>
  </div>
</template>

<script>
import { mapActions } from 'vuex'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'Login',
  data() {
    return {
      form: {
        firstName: '',
        lastName: '',
        email: '',
        password: ''
      },
      loading: false,
      error: null,
      isLoginMode: true
    }
  },
  methods: {
    ...mapActions('auth', ['login', 'register']),
    toggleMode() {
      this.isLoginMode = !this.isLoginMode
      // Clear first and last name when switching to login mode
      if (this.isLoginMode) {
        this.form.firstName = ''
        this.form.lastName = ''
      }
    },
    async handleLogin() {
      this.loading = true
      
      try {
        const response = await this.login({
          email: this.form.email,
          password: this.form.password
        })
        
        // Login successful - redirect based on hasAddress
        if (!response.hasAddress) {
          this.$router.push('/address')
        } else {
          this.$router.push('/restaurants')
        }
      } catch (error) {
        const errorMessage = error.response.data
        showAlert('Login Failed', errorMessage);
        window.location.reload();
      } finally {
        this.loading = false
      }
    },
    async handleRegister() {
      this.loading = true
      
      try {
        const response = await this.register({
          firstName: this.form.firstName,
          lastName: this.form.lastName,
          email: this.form.email,
          password: this.form.password
        })
        
        // Registration successful - redirect based on hasAddress
        if (!response.hasAddress) {
          this.$router.push('/address')
        } else {
          this.$router.push('/restaurants')
        }
      } catch (error) {
        const errorMessage = error.response.data
        showAlert('Registration Failed', errorMessage);
        window.location.reload();
      } finally {
        this.loading = false
      }
    }
  }
}
</script>

<style scoped>
.login-container {
  width: 100%;
  min-height: 100vh;
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  position: relative;
  background: #FFFBFE;
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.login-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: #FFFFFF;
  width: 100%;
  max-width: 100%;
  padding: 0;
  margin: 0;
  position: relative;
  z-index: 1;
}

.welcome-header {
  text-align: center;
  margin-bottom: 32px;
  padding-top: calc(env(safe-area-inset-top, 0px) + 16px);
}

.welcome-header h2 {
  color: rgba(0, 0, 0, 0.87);
  font-size: 28px;
  font-weight: 500;
  margin: 0;
  letter-spacing: -0.3px;
  line-height: 36px;
  font-family: 'Roboto', sans-serif;
}

.welcome-subtitle {
  color: rgba(0, 0, 0, 0.6);
  font-size: 12px;
  font-weight: 400;
  margin: 6px 0 0 0;
  letter-spacing: 0.1px;
  line-height: 16px;
  font-family: 'Roboto', sans-serif;
}

.login-form {
  flex: 1;
  width: 100%;
  padding: calc(env(safe-area-inset-top, 0px) + 24px) 24px 32px 24px;
  padding-bottom: calc(env(safe-area-inset-bottom) + 32px);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.login-form .form-group {
  width: 100%;
  box-sizing: border-box;
}

.form-group {
  margin-bottom: 20px;
}

.forgot-password-container {
  text-align: right;
  margin-top: -12px;
  margin-bottom: 24px;
}

.forgot-password-link {
  color: #C2410C;
  font-size: 14px;
  text-decoration: none;
  font-weight: 500;
  letter-spacing: 0.1px;
  transition: color 0.15s cubic-bezier(0.4, 0.0, 0.2, 1);
  font-family: 'Roboto', sans-serif;
}

.forgot-password-link:hover {
  color: #7E6FA8;
}

.form-group {
  position: relative;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: rgba(0, 0, 0, 0.87);
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.1px;
  line-height: 20px;
  font-family: 'Roboto', sans-serif;
}

.form-input {
  width: 100%;
  padding: 14px 16px;
  border: 1.5px solid rgba(0, 0, 0, 0.23);
  border-radius: 8px;
  font-size: 16px;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  outline: none;
  font-family: 'Roboto', sans-serif;
  background: #FFFFFF;
  -webkit-appearance: none;
  appearance: none;
  min-height: 52px;
  color: rgba(0, 0, 0, 0.87);
  box-sizing: border-box;
}

.form-input::placeholder {
  color: rgba(0, 0, 0, 0.38);
}

.form-input:focus {
  border-color: #C2410C;
  border-width: 2px;
  background: #FFFFFF;
  box-shadow: 0 0 0 3px rgba(194, 65, 12, 0.1);
}

.form-input:disabled {
  background-color: rgba(0, 0, 0, 0.04);
  border-color: rgba(0, 0, 0, 0.12);
  cursor: not-allowed;
  opacity: 0.6;
}

.error-message {
  background-color: #fff5f5;
  color: #c53030;
  padding: 14px 16px;
  border-radius: 12px;
  margin-bottom: 20px;
  font-size: 14px;
  border: 1.5px solid #fed7d7;
  line-height: 1.5;
}

.login-button {
  width: 100%;
  padding: 16px 24px;
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  color: #FFFFFF;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.15px;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  margin-top: 8px;
  margin-bottom: 16px;
  min-height: 48px;
  box-shadow: 0px 2px 4px rgba(194, 65, 12, 0.2), 0px 1px 2px rgba(0, 0, 0, 0.1);
  -webkit-tap-highlight-color: transparent;
  font-family: 'Roboto', sans-serif;
  position: relative;
  overflow: hidden;
}

.login-button::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.3s cubic-bezier(0.4, 0.0, 0.2, 1), height 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.login-button:active:not(:disabled)::before {
  width: 300px;
  height: 300px;
}

.login-button:disabled {
  background: rgba(0, 0, 0, 0.12);
  color: rgba(0, 0, 0, 0.38);
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.6;
}

.login-button:hover:not(:disabled) {
  box-shadow: 0px 4px 8px rgba(194, 65, 12, 0.3), 0px 2px 4px rgba(0, 0, 0, 0.15);
  transform: translateY(-1px);
}

.auth-toggle {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.6);
  line-height: 20px;
  letter-spacing: 0.1px;
  font-family: 'Roboto', sans-serif;
}

.toggle-link {
  background: none;
  border: none;
  color: #C2410C;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.1px;
  cursor: pointer;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 2px;
  -webkit-tap-highlight-color: transparent;
  transition: color 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  font-family: 'Roboto', sans-serif;
}

.toggle-link:hover {
  color: #EA580C;
}

.toggle-link:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

/* Mobile styles applied to all screens */
.welcome-header {
  padding-top: 8px;
  margin-bottom: 28px;
}

.welcome-header h2 {
  font-size: 24px;
  line-height: 32px;
}

.login-form {
  padding: calc(env(safe-area-inset-top, 0px) + 20px) 20px 28px 20px;
  padding-bottom: calc(env(safe-area-inset-bottom) + 28px);
}

.form-group {
  margin-bottom: 20px;
}
</style>
