<template>
  <div class="contact-us-container">
    <div class="contact-us-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>Contact Us</h1>
        <p v-if="complaints.length > 0">{{ complaints.length }} complaint{{ complaints.length !== 1 ? 's' : '' }}</p>
      </div>
    </div>

    <div class="contact-us-content">
      <button @click="showCreateModal = true" class="create-complaint-button">
        <span class="button-icon">+</span>
        Create New Complaint
      </button>

      <div v-if="loading" class="loading-container">
        <div class="loading-spinner"></div>
        <p>Loading complaints...</p>
      </div>

      <div v-else-if="complaints.length === 0" class="empty-complaints">
        <div class="empty-icon">📝</div>
        <h2>No complaints yet</h2>
        <p>Your complaints will appear here</p>
      </div>

      <div v-else class="complaints-list">
        <div
          v-for="complaint in complaints"
          :key="complaint.id"
          class="complaint-card"
        >
          <div class="complaint-header">
            <div class="complaint-info">
              <h3 class="complaint-id">Complaint #{{ complaint.id }}</h3>
              <p class="complaint-date">{{ formatDate(complaint.createdAt) }}</p>
              <div class="status-badge" :class="getStatusClass(complaint.status)">
                {{ getStatusText(complaint.status) }}
              </div>
            </div>
          </div>

          <div class="complaint-body">
            <p class="complaint-issue">{{ complaint.issue }}</p>
            
            <div v-if="complaint.imageUrl" class="complaint-image-container">
              <img
                :src="getImageUrl(complaint.imageUrl)"
                :alt="'Complaint image ' + complaint.id"
                class="complaint-image"
                @error="handleImageError"
              />
            </div>

            <div v-if="complaint.orderNumber" class="complaint-order">
              <span class="order-label">Order #:</span>
              <span class="order-number">{{ complaint.orderNumber }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Create Complaint Modal -->
    <div v-if="showCreateModal" class="modal-overlay" @click.self="closeModal">
      <div class="modal-content">
        <div class="modal-header">
          <h2>Create New Complaint</h2>
          <button @click="closeModal" class="close-button">×</button>
        </div>

        <form @submit.prevent="submitComplaint" class="complaint-form">
          <div class="form-group">
            <label for="issue">Issue Description *</label>
            <textarea
              id="issue"
              v-model="newComplaint.issue"
              rows="5"
              placeholder="Please describe your issue..."
              required
              class="form-input"
            ></textarea>
          </div>

          <div class="form-group">
            <label for="file">Upload Image (Optional)</label>
            <label for="file" class="file-input-label">
              Choose File
            </label>
            <input
              id="file"
              type="file"
              accept="image/*"
              @change="handleFileSelect"
              class="file-input"
            />
            <div v-if="selectedFile" class="file-info">
              <span>{{ selectedFile.name }}</span>
              <button type="button" @click="selectedFile = null" class="remove-file">×</button>
            </div>
          </div>

          <div class="form-group">
            <label for="orderNumber">Order Number *</label>
            <input
              id="orderNumber"
              v-model.number="newComplaint.orderNumber"
              type="number"
              placeholder="Enter order number"
              required
              min="1"
              class="form-input"
            />
          </div>

          <div class="form-actions">
            <button type="button" @click="closeModal" class="cancel-button">Cancel</button>
            <button type="submit" :disabled="submitting" class="submit-button">
              <span v-if="submitting">Submitting...</span>
              <span v-else>Submit Complaint</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  </div>
</template>

<script>
import api from '@/services/api'

export default {
  name: 'ContactUs',
  data() {
    return {
      complaints: [],
      loading: false,
      showCreateModal: false,
      selectedFile: null,
      submitting: false,
      newComplaint: {
        issue: '',
        orderNumber: null
      }
    }
  },
  mounted() {
    this.loadComplaints()
  },
  methods: {
    async loadComplaints() {
      this.loading = true
      try {
        const token = localStorage.getItem('token')
        const response = await api.get('/auth/client/complaints', {
          headers: {
            Authorization: `Bearer ${token}`
          }
        })
        this.complaints = response.data || []
      } catch (error) {
        console.error('Failed to load complaints:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Failed to load complaints. Please try again.'
        alert(errorMessage)
      } finally {
        this.loading = false
      }
    },
    handleFileSelect(event) {
      this.selectedFile = event.target.files[0]
    },
    async submitComplaint() {
      if (!this.newComplaint.issue.trim()) {
        alert('Please enter an issue description')
        return
      }

      if (!this.newComplaint.orderNumber || this.newComplaint.orderNumber <= 0) {
        alert('Please enter a valid order number')
        return
      }

      this.submitting = true
      try {
        const token = localStorage.getItem('token')
        const formData = new FormData()
        formData.append('issues', this.newComplaint.issue)
        formData.append('orderNumber', this.newComplaint.orderNumber.toString())
        
      if (this.selectedFile) {
          formData.append('file', this.selectedFile)
        }

        await api.post('/auth/client/upload', formData, {
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'multipart/form-data'
          }
        })

        // Reset form
        this.newComplaint = { issue: '', orderNumber: null }
        this.selectedFile = null
        this.showCreateModal = false

        // Reload complaints
        await this.loadComplaints()
        
        alert('Complaint submitted successfully!')
      } catch (error) {
        console.error('Failed to submit complaint:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Failed to submit complaint. Please try again.'
        alert(errorMessage)
      } finally {
        this.submitting = false
      }
    },
    closeModal() {
      if (!this.submitting) {
        this.showCreateModal = false
        this.newComplaint = { issue: '', orderNumber: null }
        this.selectedFile = null
      }
    },
    formatDate(dateString) {
      const date = new Date(dateString)
      return date.toLocaleDateString('en-GB', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    },
    getStatusText(status) {
      const statusMap = {
        0: 'Pending',
        1: 'In Progress',
        2: 'Resolved',
        3: 'Closed'
      }
      return statusMap[status] || 'Unknown'
    },
    getStatusClass(status) {
      const classMap = {
        0: 'status-pending',
        1: 'status-progress',
        2: 'status-resolved',
        3: 'status-closed'
      }
      return classMap[status] || 'status-pending'
    },
    getImageUrl(imageUrl) {
      if (!imageUrl) return ''
      // If it's already a full URL, return as is
      if (imageUrl.startsWith('http://') || imageUrl.startsWith('https://')) {
        return imageUrl
      }
      // Otherwise, construct the URL from the backend
      // Remove leading space if present and construct URL
      const baseURL = 'http://localhost:8080'.trim()
      // Ensure imageUrl doesn't start with / to avoid double slashes
      const cleanImageUrl = imageUrl.startsWith('/') ? imageUrl.substring(1) : imageUrl
      return `${baseURL}/${cleanImageUrl}`
    },
    handleImageError(event) {
      event.target.src = 'https://via.placeholder.com/400x300?text=Image+Not+Available'
    },
    goBack() {
      this.$router.go(-1)
    }
  }
}
</script>

