<template>
  <div>
    <!-- Overlay -->
    <transition name="fade">
      <div 
        v-if="isOpen" 
        class="drawer-overlay" 
        @click="closeDrawer"
        @touchstart="handleTouchStart"
        @touchmove="handleTouchMove"
        @touchend="handleTouchEnd"
      ></div>
    </transition>

    <!-- Drawer -->
    <transition name="slide">
      <aside 
        v-if="isOpen" 
        class="drawer"
        :class="{ 'drawer-dragging': isDragging }"
        :style="isDragging ? { transform: `translateX(${drawerOffset}px)` } : {}"
        @touchstart="handleDrawerTouchStart"
        @touchmove="handleDrawerTouchMove"
        @touchend="handleDrawerTouchEnd"
      >
        <div class="drawer-header">
          <div class="drawer-header-content">
            <div class="drawer-header-title">
              <h2 class="drawer-title">Menu</h2>
            </div>
            <button class="drawer-close-button" @click="closeDrawer" aria-label="Close menu">
              <svg class="close-icon" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M18 6L6 18M6 6L18 18" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </button>
          </div>
        </div>
        
        <div class="drawer-content">
          <slot></slot>
        </div>
        <div class="drawer-footer">
          <p class="drawer-version">Version 1.0.1</p>
        </div>
      </aside>
    </transition>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'

export default {
  name: 'SlideDrawer',
  props: {
    title: {
      type: String,
      default: 'Menu'
    }
  },
  computed: {
    ...mapGetters('drawer', ['isOpen'])
  },
  watch: {
    isOpen(newVal) {
      // Handle body scroll prevention
      if (newVal) {
        document.body.classList.add('drawer-open')
        this.drawerOffset = 0
      } else {
        document.body.classList.remove('drawer-open')
        this.drawerOffset = 0
      }
    }
  },
  data() {
    return {
      touchStartX: null,
      drawerTouchStartX: null,
      drawerOffset: 0,
      isDragging: false
    }
  },
  mounted() {
    // Close drawer on escape key
    document.addEventListener('keydown', this.handleEscape)
    // Ensure body class is set correctly on mount
    if (this.isOpen) {
      document.body.classList.add('drawer-open')
    }
  },
  beforeDestroy() {
    document.removeEventListener('keydown', this.handleEscape)
    // Clean up body class
    document.body.classList.remove('drawer-open')
  },
  methods: {
    ...mapActions('drawer', ['closeDrawer']),
    handleEscape(e) {
      if (e.key === 'Escape' && this.isOpen) {
        this.closeDrawer()
      }
    },
    handleTouchStart(e) {
      this.touchStartX = e.touches[0].clientX
    },
    handleTouchMove(e) {
      if (this.touchStartX !== null && !this.isDragging) {
        const touchX = e.touches[0].clientX
        const diff = touchX - this.touchStartX
        if (diff > 20) {
          // Swiping right - allow it
          e.preventDefault()
        }
      }
    },
    handleTouchEnd(e) {
      if (this.touchStartX !== null) {
        const touchEndX = e.changedTouches[0].clientX
        const diff = touchEndX - this.touchStartX
        // If swiped right more than 100px, close drawer
        if (diff > 100) {
          this.closeDrawer()
        }
      }
      this.touchStartX = null
      this.isDragging = false
    },
    handleDrawerTouchStart(e) {
      this.drawerTouchStartX = e.touches[0].clientX
      this.isDragging = true
    },
    handleDrawerTouchMove(e) {
      if (this.drawerTouchStartX !== null && this.isDragging) {
        const touchX = e.touches[0].clientX
        const diff = touchX - this.drawerTouchStartX
        
        // Only allow dragging to the right (closing)
        if (diff > 0) {
          this.drawerOffset = Math.min(diff, 320)
          e.preventDefault()
        }
      }
    },
    handleDrawerTouchEnd(e) {
      if (this.drawerTouchStartX !== null) {
        const touchEndX = e.changedTouches[0].clientX
        const diff = touchEndX - this.drawerTouchStartX
        
        // If swiped right more than 100px, close drawer
        if (diff > 100) {
          this.closeDrawer()
        } else {
          // Snap back
          this.drawerOffset = 0
        }
      }
      this.drawerTouchStartX = null
      this.isDragging = false
    }
  }
}
</script>

<style scoped>
.drawer-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 1000;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: opacity 0.25s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.drawer {
  position: fixed;
  top: 0;
  left: 0;
  width: 320px;
  max-width: calc(100vw - 64px);
  height: 100vh;
  height: 100dvh;
  background: #FFFFFF;
  z-index: 1001;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  will-change: transform;
  box-shadow: 0px 8px 10px 1px rgba(0, 0, 0, 0.14),
              0px 3px 14px 2px rgba(0, 0, 0, 0.12),
              0px 5px 5px -3px rgba(0, 0, 0, 0.2);
}

.drawer-dragging {
  transition: none !important;
}

.drawer-header {
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  padding: calc(env(safe-area-inset-top, 0px) + 12px) 24px 12px 24px;
  min-height: 48px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  box-shadow: 0px 2px 8px rgba(0, 0, 0, 0.15);
  position: relative;
  z-index: 1;
}

.drawer-header::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
}

.drawer-header-content {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.drawer-header-title {
  flex: 1;
}

.drawer-title {
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 18px;
  font-weight: 500;
  letter-spacing: 0.1px;
  margin: 0;
  color: #FFFFFF;
  line-height: 1.5;
}

.drawer-logo {
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  transition: transform 0.2s ease;
}

.drawer-logo:hover {
  transform: scale(1.05);
}

.drawer-close-button {
  background: rgba(255, 255, 255, 0.15);
  border: none;
  border-radius: 50%;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
  flex-shrink: 0;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0px 2px 4px rgba(0, 0, 0, 0.1);
}

.drawer-close-button:hover {
  background: rgba(255, 255, 255, 0.25);
  transform: rotate(90deg);
  box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.15);
}

.drawer-close-button:active {
  background: rgba(255, 255, 255, 0.2);
  transform: rotate(90deg) scale(0.95);
  box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.1);
}

.close-icon {
  color: #FFFFFF;
  stroke-width: 2.5;
  transition: transform 0.2s ease;
}


.drawer-content {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  padding: 8px 0;
  background: #FFFFFF;
  scrollbar-width: thin;
  scrollbar-color: rgba(0, 0, 0, 0.2) transparent;
}

.drawer-content::-webkit-scrollbar {
  width: 6px;
}

.drawer-content::-webkit-scrollbar-track {
  background: transparent;
}

.drawer-content::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.2);
  border-radius: 3px;
}

.drawer-content::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.3);
}

.drawer-footer {
  padding: 16px 24px;
  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 16px);
  background: #FFFFFF;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  flex-shrink: 0;
}

.drawer-version {
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 12px;
  font-weight: 400;
  color: rgba(0, 0, 0, 0.54);
  letter-spacing: 0.4px;
  line-height: 16px;
  margin: 0;
  text-align: center;
}

/* Transitions */
.fade-enter-active {
  transition: opacity 0.25s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.fade-leave-active {
  transition: opacity 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.fade-enter,
.fade-leave-to {
  opacity: 0;
}

.slide-enter-active {
  transition: transform 0.25s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.slide-leave-active {
  transition: transform 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.slide-enter {
  transform: translateX(-100%);
}

.slide-enter-to {
  transform: translateX(0);
}

.slide-leave {
  transform: translateX(0);
}

.slide-leave-to {
  transform: translateX(-100%);
}


/* Prevent body scroll when drawer is open */
body.drawer-open {
  overflow: hidden;
  position: fixed;
  width: 100%;
  height: 100%;
}
</style>
