<template>
  <div class="restaurants-container">
    <CartButton v-if="isAuthenticated" />
    <div class="restaurants-header">
      <MenuButton v-if="isAuthenticated" />
      <div class="header-content">
        <h1>Naija Meals</h1>
        <p>Find your favorite meals nearby</p>
      </div>
    </div>
    
    <div class="search-container">
      <div class="search-input-wrapper">
        <span class="search-icon">🔍</span>
        <input
          v-model="searchQuery"
          type="text"
          placeholder="Search restaurants..."
          class="search-input"
          @input="handleSearch"
        />
        <button
          v-if="searchQuery"
          class="clear-search-button"
          @click="clearSearch"
          aria-label="Clear search"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <circle cx="12" cy="12" r="10" fill="rgba(0, 0, 0, 0.38)"/>
            <path d="M15 9L9 15M9 9L15 15" stroke="white" stroke-width="2" stroke-linecap="round"/>
          </svg>
        </button>
      </div>
    </div>
    
    <div v-if="loading" class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading restaurants...</p>
    </div>
    
    <div v-else-if="error" class="error-container">
      <button @click="loadRestaurants()" class="retry-button">Try Again</button>
    </div>
    
    <div v-else-if="restaurants.length === 0" class="empty-container">
      <p>No restaurants found in your area</p>
    </div>
    
    <div v-else-if="filteredRestaurants.length === 0 && searchQuery" class="empty-container">
      <p>No restaurants found matching "{{ searchQuery }}"</p>
    </div>
    
    <div v-else class="restaurants-list">
      <div
        v-for="item in filteredRestaurants"
        :key="item.restaurant.id"
        class="restaurant-card"
        :class="{ 'restaurant-disabled': !item.restaurant.active }"
        @click="item.restaurant.active && selectRestaurant(item.restaurant)"
      >
        <div class="restaurant-image-container">
          <img
            :src="item.restaurant.image"
            :alt="item.restaurant.name"
            class="restaurant-image"
            @error="handleImageError"
          />
          <div v-if="item.restaurant.isPromoted" class="promoted-badge">Promoted</div>
          <div v-if="item.restaurant.freeDelivery" class="delivery-badge">Free Delivery</div>
        </div>
        
        <div class="restaurant-info">
          <h3 class="restaurant-name">{{ item.restaurant.name }}</h3>
          
          <div class="restaurant-rating">
            <span class="rating-stars">★</span>
            <span class="rating-value">{{ item.restaurant.rating }}</span>
            <span class="review-count">({{ item.restaurant.reviewCount }})</span>
          </div>
          
          <div class="restaurant-details">
            <div class="detail-item">
              <span class="detail-icon">🏍️</span>
              <span class="detail-label">Distance:</span>
              <span class="detail-value">{{ item.distanceMiles }}</span>
            </div>
            <div class="detail-item">
              <span class="detail-icon">⏱️</span>
              <span class="detail-label">Time:</span>
              <span class="detail-value">{{ item.estimatedTime }}</span>
            </div>
          </div>
          
          <div class="restaurant-address">
            <span class="address-icon">📍</span>
            <span class="address-text">{{ item.restaurant.fullAddress }}</span>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'
import CartButton from '@/components/CartButton.vue'
import MenuButton from '@/components/MenuButton.vue'
import { showAlert, showToast, vibrate, getErrorMessage } from '@/utils/webUtils'

export default {
  name: 'Restaurants',
  components: {
    CartButton,
    MenuButton
  },
  data() {
    return {
      restaurants: [],
      loading: false,
      error: null,
      searchQuery: ''
    }
  },
  computed: {
    ...mapGetters('auth', ['postcode', 'isAuthenticated']),
    filteredRestaurants() {
      if (!this.searchQuery.trim()) {
        return this.restaurants
      }
      
      const query = this.searchQuery.toLowerCase().trim()
      return this.restaurants.filter(item => {
        const name = (item.restaurant.name || '').toLowerCase()
        const address = (item.restaurant.fullAddress || '').toLowerCase()
        return name.includes(query) || address.includes(query)
      })
    }
  },
  mounted() {
    if (this.isAuthenticated) {
      this.loadRestaurants()
    } else {
      // Redirect to landing page if not authenticated
      this.$router.push('/')
    }
  },
  methods: {
    ...mapActions('auth', ['fetchRestaurants', 'logout']),
    ...mapActions('cart', ['clearCart']),
    handleSearch() {
      // Search is handled by computed property filteredRestaurants
    },
    clearSearch() {
      this.searchQuery = ''
    },
    async loadRestaurants() {
      if (!this.isAuthenticated) {
        this.redirectToLogin()
        return
      }
      
      this.loading = true
      this.error = null
      
      try {
        const data = await this.fetchRestaurants()
        this.restaurants = data || []
      } catch (error) {
        const errorMessage = getErrorMessage(error, 'Failed to load restaurants. Please try again.')
        showAlert('Load Restaurants Failed', errorMessage)
        this.error = true // Keep error flag for UI state
      } finally {
        this.loading = false
      }
    },
    selectRestaurant(restaurant) {
      if (!this.isAuthenticated) {
        this.redirectToLogin()
        return
      }
      // Check if user is selecting a different restaurant
      const selectedRestaurant = localStorage.getItem('selectedRestaurant')
      let isDifferentRestaurant = true

      vibrate(8);
      
      if (selectedRestaurant) {
        try {
          const parsed = JSON.parse(selectedRestaurant)
          isDifferentRestaurant = parsed.id !== restaurant.id
        } catch (e) {
          // If parsing fails, treat as different restaurant
          isDifferentRestaurant = true
        }
      }
      
      // Clear cart if selecting a different restaurant
      if (isDifferentRestaurant) {
        this.clearCart()
        showToast('Your cart is now cleared');
      }
      
      // Store restaurant info in localStorage
      localStorage.setItem('selectedRestaurant', JSON.stringify(restaurant))
      
      this.$router.push({
        name: 'RestaurantMenu',
        params: {
          id: restaurant.id,
          restaurant: restaurant
        }
      })
    },

    proceedToClear(){
      this.clearCart()
    },

    handleImageError(event) {
      event.target.src = 'https://naijameals.com/img/coming_soon.jpg'
    }
  }
}
</script>

