<template>
  <div class="menu-container">
    <CartButton />
    <div class="menu-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>{{ restaurantName }}</h1>
        <p v-if="restaurantAddress">{{ restaurantAddress }}</p>
      </div>
    </div>


<!--    menu filters call a function and pass in the category id-->
    <div class="filter-container" :style="{ top: filterTop + 'px' }">
      <!-- Search Bar -->
      <div class="search-container">
        <div class="search-input-wrapper">
          <span class="search-icon">🔍</span>
          <input
            v-model="searchQuery"
            type="text"
            placeholder="Search menu items..."
            class="search-input"
            @input="handleSearch"
          />
          <button
            v-if="searchQuery"
            class="clear-search-button"
            @click="clearSearch"
            aria-label="Clear search"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M18 6L6 18M6 6L18 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
            </svg>
          </button>
        </div>
        <button 
          class="filter-icon-button" 
          @click="openFilterModal"
          aria-label="Filter categories"
        >
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M4 6H20M4 12H20M4 18H20" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
            <circle cx="7" cy="6" r="2" fill="currentColor"/>
            <circle cx="17" cy="12" r="2" fill="currentColor"/>
            <circle cx="7" cy="18" r="2" fill="currentColor"/>
          </svg>
          <span v-if="selectedCategories.length > 0" class="filter-badge">{{ selectedCategories.length }}</span>
        </button>
      </div>
      
    </div>

    <!-- Filter Modal -->
    <transition name="modal">
      <div v-if="showFilterModal" class="filter-modal-overlay" @click="closeFilterModal">
        <div class="filter-modal-content" @click.stop>
          <div class="filter-modal-header">
            <h2>Filter by Category</h2>
            <button class="filter-modal-close" @click="closeFilterModal" aria-label="Close">
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M18 6L6 18M6 6L18 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </button>
          </div>
          <div class="filter-modal-body">
            <div class="filter-option">
              <label class="checkbox-label">
                <input
                  type="checkbox"
                  :checked="selectedCategories.length === 0"
                  @change="toggleAllCategories"
                  class="checkbox-input"
                />
                <span class="checkbox-custom"></span>
                <span class="checkbox-text">All Categories</span>
              </label>
            </div>
            <div
              v-for="category in availableCategories"
              :key="category.id"
              class="filter-option"
            >
              <label class="checkbox-label">
                <input
                  type="checkbox"
                  :value="category.id"
                  :checked="selectedCategories.includes(category.id)"
                  @change="toggleCategory(category.id)"
                  class="checkbox-input"
                />
                <span class="checkbox-custom"></span>
                <span class="checkbox-text">{{ category.name }}</span>
              </label>
            </div>
          </div>
          <div class="filter-modal-footer">
            <button class="filter-reset-button" @click="resetFilters">Reset</button>
            <button class="filter-apply-button" @click="applyFilters">Apply</button>
          </div>
        </div>
      </div>
    </transition>

    <div v-if="loading" class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading menu...</p>
    </div>
    
    <div v-else-if="error" class="error-container">
      <button @click="loadMenuItems" class="retry-button">Try Again</button>
    </div>
    
    <div v-else-if="items.length === 0" class="empty-container">
      <p>No items available</p>
    </div>

    <div v-else-if="filteredItems.length === 0 && searchQuery" class="empty-container">
      <p>No items found matching "{{ searchQuery }}"</p>
    </div>

    <div v-else class="menu-items-list">
      <div
        v-for="item in filteredItems"
        :key="item.id"
        class="menu-item"
        :class="{ 'out-of-stock': !item.inStock }"
      >
        <div class="item-content">
          <div class="item-image-wrapper" @click="openItemModal(item)">
            <img
              :src="item.image"
              :alt="item.name"
              class="item-image"
              @error="handleImageError"
            />
            <div v-if="!item.inStock" class="stock-overlay">
              <span class="stock-badge">Unavailable</span>
            </div>
            <div v-if="item.isExtra" class="extra-tag">Extra</div>
          </div>

          <div class="item-details">
            <div class="item-title-row">
              <h3 class="item-title">{{ item.name }}</h3>
              <div class="price-badge">£{{ item.price.toFixed(2) }}</div>
            </div>

            <p v-if="item.description" class="item-desc">{{ item.description }}</p>

            <div class="item-actions">
              <div class="left-actions">
                <button
                  v-if="item.inStock"
                  class="add-btn"
                  @click="addToCart(item)"
                >
                  <span class="btn-icon">+</span>
                  <span class="btn-text">Add</span>
                </button>
                <div v-else class="unavailable-message">Currently unavailable</div>
              </div>
              <span
                class="read-more-icon"
                @click="openItemModal(item)"
                aria-label="More info"
                role="button"
                tabindex="0"
              >
                <span class="read-more-text">More info</span>
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="12" cy="12" r="10" fill="#10b981" stroke="#10b981" stroke-width="1"/>
                  <path d="M12 16V12M12 8H12.01" stroke="white" stroke-width="2" stroke-linecap="round"/>
                  <circle cx="12" cy="8" r="1" fill="white"/>
                </svg>
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Item Detail Modal -->
    <div v-if="selectedItem" class="modal-overlay" @click="closeItemModal">
      <div class="modal-content" @click.stop>
        <button class="modal-close" @click="closeItemModal" aria-label="Close">
          ×
        </button>
        <div class="modal-image-container">
          <img
            :src="selectedItem.image"
            :alt="selectedItem.name"
            class="modal-image"
            @error="handleImageError"
          />
          <div v-if="!selectedItem.inStock" class="modal-stock-overlay">
            <span class="modal-stock-badge">Unavailable</span>
          </div>
          <div v-if="selectedItem.isExtra" class="modal-extra-tag">Extra</div>
        </div>
        <div class="modal-body">
          <div class="modal-header">
            <h2 class="modal-title">{{ selectedItem.name }}</h2>
            <div class="modal-price">£{{ selectedItem.price.toFixed(2) }}</div>
          </div>
          <p v-if="selectedItem.description" class="modal-description">{{ selectedItem.description }}</p>
          <button
            v-if="selectedItem.inStock"
            class="modal-add-btn"
            @click="addToCartFromModal(selectedItem)"
          >
            <span class="btn-icon">+</span>
            <span class="btn-text">Add to Cart</span>
          </button>
          <div v-else class="modal-unavailable">Currently unavailable</div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapActions } from 'vuex'
import CartButton from '@/components/CartButton.vue'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'RestaurantMenu',
  components: {
    CartButton
  },
  data() {
    return {
      restaurantId: null,
      restaurantName: '',
      restaurantAddress: '',
      items: [],
      loading: false,
      error: null,
      selectedCategory: null,
      selectedCategories: [],
      showFilterModal: false,
      filterTop: 0,
      selectedItem: null,
      searchQuery: '',
      categories: [
        { id: 1, name: 'Starters' },
        { id: 2, name: 'Beans and Rice Meal' },
        { id: 4, name: 'Soup and Swallow' },
        { id: 5, name: 'Grilled' },
        { id: 6, name: 'Yam and Special Meal' },
        { id: 7, name: 'Meat and Fish Meal' },
        { id: 8, name: 'Non Alcoholic Drinks' },
        { id: 16, name: 'Drinks' },
        { id: 17, name: 'Main Menu' },
        { id: 19, name: 'Dessert' }
      ]
    }
  },
  computed: {
    filteredItems() {
      let filtered = this.items

      // Filter by categories (support multiple selection)
      if (this.selectedCategories.length > 0) {
        filtered = filtered.filter(item => this.selectedCategories.includes(item.category))
      }

      // Filter by search query
      if (this.searchQuery.trim()) {
        const query = this.searchQuery.toLowerCase().trim()
        filtered = filtered.filter(item => {
          const name = (item.name || '').toLowerCase()
          const description = (item.description || '').toLowerCase()
          return name.includes(query) || description.includes(query)
        })
      }

      return filtered
    },
    availableCategories() {
      // Only show categories that have items
      const categoryIds = new Set(this.items.map(item => item.category).filter(cat => cat != null))
      return this.categories.filter(cat => categoryIds.has(cat.id))
    }
  },
  mounted() {
    this.restaurantId = parseInt(this.$route.params.id)
    this.loadRestaurantInfo()
    this.loadMenuItems()
    this.updateFilterTop()
    window.addEventListener('resize', this.updateFilterTop)
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateFilterTop)
    // Restore body scroll if modal was open
    document.body.style.overflow = ''
  },
  watch: {
    '$route.params.id'(newId) {
      if (newId) {
        this.restaurantId = parseInt(newId)
        this.loadRestaurantInfo()
        this.loadMenuItems()
      }
    }
  },
  methods: {
    ...mapActions('auth', ['fetchRestaurantItems', 'setPreferredRestaurant']),
    loadRestaurantInfo() {
      // Get restaurant info from route params first
      let restaurant = this.$route.params.restaurant
      
      // If not in route params, try to get from localStorage
      if (!restaurant) {
        const storedRestaurant = localStorage.getItem('selectedRestaurant')
        if (storedRestaurant) {
          try {
            const parsed = JSON.parse(storedRestaurant)
            // Verify the stored restaurant matches current restaurant ID
            if (parsed.id === this.restaurantId) {
              restaurant = parsed
            }
          } catch (e) {
            console.error('Failed to parse stored restaurant:', e)
          }
        }
      }
      
      // If we have restaurant data and it matches, use it
      if (restaurant && restaurant.id === this.restaurantId) {
        this.restaurantName = restaurant.name || 'Restaurant'
        this.restaurantAddress = restaurant.fullAddress || ''
        // Update localStorage with current restaurant
        localStorage.setItem('selectedRestaurant', JSON.stringify(restaurant))
      } else {
        // Fetch from restaurants list
        this.fetchRestaurantFromList()
      }
    },
    async fetchRestaurantFromList() {
      try {
        const restaurants = await this.$store.dispatch('auth/fetchRestaurants')
        const restaurant = restaurants.find(r => r.restaurant.id === this.restaurantId)
        if (restaurant && restaurant.restaurant) {
          this.restaurantName = restaurant.restaurant.name
          this.restaurantAddress = restaurant.restaurant.fullAddress
          localStorage.setItem('selectedRestaurant', JSON.stringify(restaurant.restaurant))
        }
      } catch (error) {
        console.error('Failed to fetch restaurant info:', error)
        // Set default values if all else fails
        this.restaurantName = 'Restaurant'
        this.restaurantAddress = ''
      }
    },
    async loadMenuItems() {
      if (!this.restaurantId) {
        showAlert('Error', 'Restaurant ID not found')
        this.error = true
        return
      }
      
      this.loading = true
      this.error = null
      
      try {
        // Notify backend about the selected restaurant
        this.setPreferredRestaurant(this.restaurantId).catch(err => {
          // Silently handle errors - this is just a notification
          console.error('Failed to set preferred restaurant:', err)
        })
        
        const data = await this.fetchRestaurantItems(this.restaurantId)
        this.items = data || []
      } catch (error) {
        const errorMessage = error.response?.data?.message || 
                    error.message || 
                    'Failed to load menu items. Please try again.'
        showAlert('Load Menu Failed', errorMessage)
        this.error = true // Keep error flag for UI state
      } finally {
        this.loading = false
      }
    },
    goBack() {
      this.$router.go(-1)
    },
    addToCart(item) {
      this.$store.dispatch('cart/addToCart', item)
     // Android.vibrate(8);
     // Android.showToast('Added '+ item.name);
      // Show feedback (you can add a toast notification here)
    },
    handleImageError(event) {
      event.target.src = 'https://naijameals.com/img/coming_soon.jpg'
    },
    filterByCategory(categoryId) {
      this.selectedCategory = categoryId
    },
    toggleCategory(categoryId) {
      const index = this.selectedCategories.indexOf(categoryId)
      if (index > -1) {
        this.selectedCategories.splice(index, 1)
      } else {
        this.selectedCategories.push(categoryId)
      }
    },
    toggleAllCategories() {
      if (this.selectedCategories.length === 0) {
        // Select all available categories
        this.selectedCategories = this.availableCategories.map(cat => cat.id)
      } else {
        // Deselect all
        this.selectedCategories = []
      }
    },
    resetFilters() {
      this.selectedCategories = []
    },
    applyFilters() {
      this.showFilterModal = false
      // Restore body scroll
      document.body.style.overflow = ''
    },
    updateFilterTop() {
      this.$nextTick(() => {
        const header = this.$el.querySelector('.menu-header')
        if (header) {
          this.filterTop = header.offsetHeight
        }
      })
    },
    openItemModal(item) {
      this.selectedItem = item
      // Prevent body scroll when modal is open
      document.body.style.overflow = 'hidden'
    },
    closeItemModal() {
      this.selectedItem = null
      // Restore body scroll
      document.body.style.overflow = ''
    },
    openFilterModal() {
      this.showFilterModal = true
      // Prevent body scroll when modal is open
      document.body.style.overflow = 'hidden'
    },
    closeFilterModal() {
      this.showFilterModal = false
      // Restore body scroll
      document.body.style.overflow = ''
    },
    addToCartFromModal(item) {
      this.addToCart(item)
      this.closeItemModal()
    },
    handleSearch() {
      // Search is handled by computed property, this is just for any additional logic if needed
    },
    clearSearch() {
      this.searchQuery = ''
    }
  }
}
</script>

<style scoped>
