  width: 100%;
  min-height: 100vh;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: #FFFBFE;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  font-family: 'Roboto', sans-serif;
}

.filter-container {
  position: sticky;
  top: 0;
  z-index: 9;
  background: white;
  box-shadow: 0px 2px 4px rgba(0, 0, 0, 0.1);
  margin-top: 0;
}

.search-container {
  padding: 12px 16px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  background: #FFFFFF;
  display: flex;
  align-items: center;
  gap: 12px;
}

.search-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  background: rgba(0, 0, 0, 0.04);
  border-radius: 8px;
  padding: 0 16px;
  min-height: 48px;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  flex: 1;
}

.search-input-wrapper:focus-within {
  background: #FFFFFF;
  box-shadow: 0 0 0 2px rgba(194, 65, 12, 0.2);
}

.search-icon {
  font-size: 20px;
  margin-right: 12px;
  flex-shrink: 0;
  color: rgba(0, 0, 0, 0.54);
}

.search-input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 16px;
  font-family: 'Roboto', sans-serif;
  color: rgba(0, 0, 0, 0.87);
  letter-spacing: 0.15px;
  padding: 0;
  min-height: 48px;
}

.search-input::placeholder {
  color: rgba(0, 0, 0, 0.38);
}

.clear-search-button {
  background: transparent;
  border: none;
  padding: 8px;
  margin-left: 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(0, 0, 0, 0.54);
  transition: color 0.15s cubic-bezier(0.4, 0.0, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
