  justify-content: space-between;
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  border-radius: 20px 20px 0 0;
}

.filter-modal-header h2 {
  font-size: 20px;
  font-weight: 600;
  color: #FFFFFF;
  margin: 0;
  letter-spacing: 0.15px;
}

