  background: rgba(255, 255, 255, 0.2);
  border: none;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: #FFFFFF;
  transition: all 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}

.filter-modal-close:hover {
  background: rgba(255, 255, 255, 0.3);
}

.filter-modal-close:active {
  background: rgba(255, 255, 255, 0.4);
  transform: scale(0.95);
}

.filter-modal-close svg {
  width: 20px;
  height: 20px;
}

.filter-modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 24px;
  max-height: calc(80vh - 140px);
}

.filter-option {
  margin-bottom: 12px;
}

.checkbox-label {
  display: flex;
  align-items: center;
  cursor: pointer;
  padding: 12px;
  border-radius: 8px;
  transition: background-color 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}

.checkbox-label:hover {
  background: rgba(0, 0, 0, 0.04);
}

.checkbox-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.checkbox-custom {
  width: 20px;
  height: 20px;
  border: 2px solid rgba(0, 0, 0, 0.38);
  border-radius: 4px;
  margin-right: 12px;
  flex-shrink: 0;
  position: relative;
  transition: all 0.2s ease;
  background: #FFFFFF;
}

.checkbox-input:checked + .checkbox-custom {
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
