}

.checkbox-text {
  font-size: 16px;
  font-weight: 400;
  color: rgba(0, 0, 0, 0.87);
  letter-spacing: 0.15px;
  flex: 1;
}

.filter-modal-footer {
  padding: 16px 24px;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  display: flex;
  gap: 12px;
  background: #FFFFFF;
}

