.filter-apply-button {
  flex: 1;
  padding: 14px 24px;
  border: none;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.1px;
  cursor: pointer;
  transition: all 0.2s ease;
  -webkit-tap-highlight-color: transparent;
  font-family: 'Roboto', sans-serif;
}

.filter-reset-button {
  background: #F5F5F5;
  color: rgba(0, 0, 0, 0.87);
}

.filter-reset-button:hover {
  background: #E0E0E0;
}

.filter-reset-button:active {
  background: #D0D0D0;
  transform: scale(0.98);
}

.filter-apply-button {
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  color: #FFFFFF;
  box-shadow: 0px 2px 4px rgba(194, 65, 12, 0.3);
}

.filter-apply-button:hover {
  box-shadow: 0px 4px 8px rgba(194, 65, 12, 0.4);
}

.filter-apply-button:active {
  transform: scale(0.98);
  box-shadow: 0px 1px 2px rgba(194, 65, 12, 0.3);
}

/* Modal Transition */
.modal-enter-active,
.modal-leave-active {
  transition: opacity 0.3s ease;
}

.modal-enter-active .filter-modal-content,
.modal-leave-active .filter-modal-content {
  transition: transform 0.3s ease;
}

.modal-enter .filter-modal-overlay,
.modal-leave-to .filter-modal-overlay {
  opacity: 0;
