<template>
  <button
    class="cart-button"
    @click="goToCart"
    aria-label="View cart"
  >
    <span class="cart-icon">🛒</span>
    <span v-if="itemCount > 0" class="cart-badge">{{ itemCount }}</span>
  </button>
</template>

<script>
import { mapGetters } from 'vuex'

export default {
  name: 'CartButton',
  computed: {
    ...mapGetters('cart', ['cartItemCount']),
    itemCount() {
      return this.cartItemCount
    }
  },
  methods: {
    goToCart() {
      this.$router.push('/cart')
    }
  }
}
</script>

<style scoped>
.cart-button {
  position: fixed;
  bottom: 16px;
  right: 16px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  border: none;
  box-shadow: 0px 3px 5px -1px rgba(0, 0, 0, 0.2), 0px 6px 10px 0px rgba(0, 0, 0, 0.14), 0px 1px 18px 0px rgba(0, 0, 0, 0.12);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  transition: box-shadow 0.15s cubic-bezier(0.4, 0.0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0.0, 0.2, 1);
  -webkit-tap-highlight-color: transparent;
  padding-bottom: calc(env(safe-area-inset-bottom, 0px));
  margin-bottom: calc(env(safe-area-inset-bottom, 0px));
  overflow: visible;
}

.cart-button::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.3s cubic-bezier(0.4, 0.0, 0.2, 1), height 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.cart-button:active::before {
  width: 200px;
  height: 200px;
}

.cart-button:active {
  box-shadow: 0px 3px 5px -1px rgba(0, 0, 0, 0.2), 0px 6px 10px 0px rgba(0, 0, 0, 0.14), 0px 1px 18px 0px rgba(0, 0, 0, 0.12);
}

.cart-icon {
  font-size: 28px;
  line-height: 1;
  display: inline-block;
  filter: brightness(0) invert(1);
}

.cart-badge {
  position: absolute;
  top: -4px;
  right: -4px;
  background: #BA1A1A;
  color: #FFFFFF;
