  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 500;
  border: 2px solid #FFFFFF;
  font-family: 'Roboto', sans-serif;
  box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.3), 0px 1px 3px 1px rgba(0, 0, 0, 0.15);
  box-sizing: border-box;
  line-height: 1;
  z-index: 1;
  white-space: nowrap;
}
</style>
