import api from '@/services/api'

const state = {
  token: localStorage.getItem('token') || null,
  hasAddress: localStorage.getItem('hasAddress') === 'true' || false,
  postcode: localStorage.getItem('postcode') || null,
  user: null
}

const mutations = {
  SET_TOKEN(state, token) {
    state.token = token
    localStorage.setItem('token', token)
  },
  SET_HAS_ADDRESS(state, hasAddress) {
    state.hasAddress = hasAddress
    localStorage.setItem('hasAddress', hasAddress.toString())
  },
  SET_POSTCODE(state, postcode) {
    state.postcode = postcode
    localStorage.setItem('postcode', postcode)
  },
  CLEAR_AUTH(state) {
    state.token = null
    state.hasAddress = false
    state.postcode = null
    state.user = null
    localStorage.removeItem('token')
    localStorage.removeItem('hasAddress')
    localStorage.removeItem('postcode')
  }
}

const actions = {
  async login({ commit }, credentials) {
    try {
      const response = await api.post('/auth/login', credentials)
      commit('SET_TOKEN', response.data.token)
      commit('SET_HAS_ADDRESS', response.data.hasAddress)
      return response.data
    } catch (error) {
      throw error
    }
  },
  async register({ commit }, credentials) {
    try {
      const response = await api.post('/auth/register', credentials)
      commit('SET_TOKEN', response.data.token)
      commit('SET_HAS_ADDRESS', response.data.hasAddress)
      return response.data
    } catch (error) {
      throw error
    }
  },
  async saveAddress({ commit }, addressData) {
    try {
      const response = await api.post('/auth/client/address', addressData)
      commit('SET_HAS_ADDRESS', true)
      // Store postcode for restaurant lookup (remove spaces and convert to lowercase)
      const postcode = addressData.postcode.replace(/\s+/g, '').toLowerCase()
      commit('SET_POSTCODE', postcode)
      return response.data
    } catch (error) {
      throw error
    }
  },
  async fetchRestaurants() {
    try {
      const response = await api.get('/api/client/restaurant/find')
      return response.data
    } catch (error) {
      throw error
    }
  },
  async fetchRestaurantItems({}, restaurantId) {
    try {
      const response = await api.get(`/api/client/restaurant/items/${restaurantId}`)
      return response.data
    } catch (error) {
      throw error
    }
  },
  async setPreferredRestaurant({}, restaurantId) {
    try {
      const response = await api.get(`/auth/client/preferred/${restaurantId}`)
      return response.data
    } catch (error) {
      // Silently fail - this is just a notification to the backend
      console.error('Failed to set preferred restaurant:', error)
      throw error
    }
  },
  async fetchOrderTracking({}, orderId) {
    try {
      // Add timestamp to prevent caching and ensure request is visible in network tab
      const timestamp = new Date().getTime()
      console.log(`[API] Making GET request to /auth/client/tracking/${orderId}?t=${timestamp}`)
      const response = await api.get(`/auth/client/tracking/${orderId}`, {
        params: { t: timestamp },
        headers: {
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache'
        }
      })
      console.log(`[API] Response received for order ${orderId}:`, response.status)
      return response.data
    } catch (error) {
      console.error(`[API] Error fetching order tracking for ${orderId}:`, error)
      throw error
    }
  },
  logout({ commit }) {
    commit('CLEAR_AUTH')
  }
}

const getters = {
  isAuthenticated: state => !!state.token,
  hasAddress: state => state.hasAddress,
  postcode: state => state.postcode
}

export default {
  namespaced: true,
  state,
  mutations,
  actions,
  getters
}
