<template>
  <div class="login-container">
    <div class="login-card">
      <div class="login-form">
        <div class="welcome-header">
          <h2>Reset Password 🔐</h2>
          <p v-if="!showResetForm" class="welcome-subtitle">Enter your email to receive a reset link</p>
          <p v-else class="welcome-subtitle">Enter your verification code and new password</p>
        </div>
        <!-- Step 1: Enter Email -->
        <div v-if="!showResetForm">
          <div class="form-group">
            <label for="email">Email Address</label>
            <input
              id="email"
              v-model="email"
              type="email"
              placeholder="Enter your email"
              required
              :disabled="loading"
              :class="['form-input', { 'input-invalid': email && !isValidEmail }]"
              @blur="emailTouched = true"
            />
            <div v-if="emailTouched && email && !isValidEmail" class="error-text">
              Please enter a valid email address
            </div>
          </div>
          
          <button
            @click="sendResetLink"
            :disabled="loading || !email || !isValidEmail"
            class="login-button"
          >
            <span v-if="loading">Sending...</span>
            <span v-else>Send Reset Link</span>
          </button>
        </div>

        <!-- Step 2: Enter Code and New Password -->
        <div v-else-if="showResetForm">
          <div class="form-group">
            <label for="code">Verification Code From Email</label>
            <input
              id="code"
              v-model="resetForm.code"
              type="text"
              placeholder="e.g. F06-E362-4"
              required
              :disabled="loading"
              class="form-input"
            />
          </div>

          <div class="form-group">
            <label for="password">New Password</label>
            <input
              id="password"
              v-model="resetForm.password"
              type="password"
              placeholder="Min 8 chars, 1 uppercase, 1 special"
              required
              :disabled="loading"
              :class="['form-input', { 'input-invalid': resetForm.password && !isPasswordValid }]"
            />
            <div v-if="resetForm.password && !isPasswordValid" class="error-text">
              Must be 8+ chars with 1 uppercase and 1 special character
            </div>
          </div>

          <div class="form-group">
            <label for="confirm_password">Confirm New Password</label>
            <input
              id="confirm_password"
              v-model="resetForm.confirm_password"
              type="password"
              placeholder="Confirm new password"
              required
              :disabled="loading"
              :class="['form-input', { 'input-invalid': resetForm.confirm_password && !passwordsMatch }]"
            />
            <div v-if="resetForm.confirm_password && !passwordsMatch" class="error-text">
              Passwords do not match
            </div>
          </div>
          
          <button
            @click="submitNewPassword"
            :disabled="loading || !isResetFormValid"
            class="login-button"
          >
            <span v-if="loading">Updating Password...</span>
            <span v-else>Reset Password</span>
          </button>
        </div>

        <div class="auth-toggle">
          <button
            type="button"
            class="toggle-link"
            @click="goBack"
            :disabled="loading"
          >
            Back to Login
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import api from '@/services/api'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'ForgotPassword',
  data() {
    return {
      email: '',
      loading: false,
      emailTouched: false,
      showResetForm: false,
      resetForm: {
        code: '',
        password: '',
        confirm_password: ''
      }
    }
  },
  computed: {
    isValidEmail() {
      const re = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
      return re.test(String(this.email).toLowerCase())
    },
    isPasswordValid() {
      const password = this.resetForm.password
      const hasMinLength = password.length >= 8
      const hasUppercase = /[A-Z]/.test(password)
      const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(password)
      return hasMinLength && hasUppercase && hasSpecial
    },
    passwordsMatch() {
      return this.resetForm.password === this.resetForm.confirm_password
    },
    isResetFormValid() {
      return this.resetForm.code && 
             this.isPasswordValid &&
             this.resetForm.confirm_password && 
             this.passwordsMatch
    }
  },
  methods: {
    goBack() {
      this.$router.push('/login')
    },
    async sendResetLink() {
      if (!this.email) return
      
      this.loading = true
      try {
        await api.post('/auth/send_reset_link', { email: this.email })
        this.showResetForm = true
      } catch (error) {
        const errorMessage = error.response?.data?.message || 
                            error.message || 
                            'Failed to send reset link. Please try again.'
        showAlert('Reset Failed', errorMessage)
      } finally {
        this.loading = false
      }
    },
    async submitNewPassword() {
      if (!this.isResetFormValid) return
      
      this.loading = true
      try {
        await api.post('/auth/reset', {
          email: this.email,
          ...this.resetForm
        })
        
        showAlert('Success', 'Password has been reset successfully')
        
        // Redirect to login page on success
        this.$router.push('/login')
      } catch (error) {
        const errorMessage = error.response?.data?.message || 
                            error.message || 
                            'Failed to reset password. Please check your code and try again.'
        showAlert('Reset Failed', errorMessage)
      } finally {
        this.loading = false
      }
    }
  }
}
</script>

<style scoped>
