  position: relative;
  background: #FFFBFE;
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.login-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: #FFFFFF;
  width: 100%;
  max-width: 100%;
  padding: 0;
  margin: 0;
  position: relative;
  z-index: 1;
}

.welcome-header {
  text-align: center;
  margin-bottom: 32px;
  padding-top: calc(env(safe-area-inset-top, 0px) + 16px);
}

.welcome-header h2 {
  color: rgba(0, 0, 0, 0.87);
  font-size: 28px;
  font-weight: 500;
  margin: 0;
  letter-spacing: -0.3px;
  line-height: 36px;
  font-family: 'Roboto', sans-serif;
}

.welcome-subtitle {
  color: rgba(0, 0, 0, 0.6);
  font-size: 12px;
  font-weight: 400;
  margin: 6px 0 0 0;
  letter-spacing: 0.1px;
  line-height: 16px;
  font-family: 'Roboto', sans-serif;
}

.login-form {
  flex: 1;
  width: 100%;
  padding: calc(env(safe-area-inset-top, 0px) + 24px) 24px 32px 24px;
  padding-bottom: calc(env(safe-area-inset-bottom) + 32px);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.login-form .form-group {
  width: 100%;
  box-sizing: border-box;
}

.form-group {
  position: relative;
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: rgba(0, 0, 0, 0.87);
  font-weight: 500;
  font-size: 14px;
  letter-spacing: 0.1px;
  line-height: 20px;
  font-family: 'Roboto', sans-serif;
}

.form-input {
  width: 100%;
  padding: 14px 16px;
  border: 1.5px solid rgba(0, 0, 0, 0.23);
  border-radius: 8px;
  font-size: 16px;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  outline: none;
  font-family: 'Roboto', sans-serif;
  background: #FFFFFF;
  -webkit-appearance: none;
  appearance: none;
  min-height: 52px;
  color: rgba(0, 0, 0, 0.87);
  box-sizing: border-box;
}

.form-input::placeholder {
  color: rgba(0, 0, 0, 0.38);
}

.form-input:focus {
  border-color: #C2410C;
  border-width: 2px;
  background: #FFFFFF;
  box-shadow: 0 0 0 3px rgba(194, 65, 12, 0.1);
}

.form-input:disabled {
  background-color: rgba(0, 0, 0, 0.04);
  border-color: rgba(0, 0, 0, 0.12);
  cursor: not-allowed;
  opacity: 0.6;
}

.error-text {
  margin-top: 6px;
  font-size: 12px;
  color: #BA1A1A;
  font-weight: 400;
  text-align: left;
  letter-spacing: 0.1px;
  line-height: 16px;
  font-family: 'Roboto', sans-serif;
}

.input-invalid {
  border-color: #BA1A1A !important;
}

.input-invalid:focus {
  border-color: #BA1A1A !important;
  border-width: 2px !important;
  box-shadow: 0 0 0 3px rgba(186, 26, 26, 0.1) !important;
}

.login-button {
  width: 100%;
  padding: 16px 24px;
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  color: #FFFFFF;
  border: none;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.15px;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  margin-top: 8px;
  margin-bottom: 16px;
  min-height: 48px;
  box-shadow: 0px 2px 4px rgba(194, 65, 12, 0.2), 0px 1px 2px rgba(0, 0, 0, 0.1);
  -webkit-tap-highlight-color: transparent;
  font-family: 'Roboto', sans-serif;
  position: relative;
  overflow: hidden;
}

.login-button::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.3s cubic-bezier(0.4, 0.0, 0.2, 1), height 0.3s cubic-bezier(0.4, 0.0, 0.2, 1);
}

.login-button:active:not(:disabled)::before {
  width: 300px;
  height: 300px;
}

.login-button:disabled {
  background: rgba(0, 0, 0, 0.12);
  color: rgba(0, 0, 0, 0.38);
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.6;
}

.login-button:hover:not(:disabled) {
  box-shadow: 0px 4px 8px rgba(194, 65, 12, 0.3), 0px 2px 4px rgba(0, 0, 0, 0.15);
  transform: translateY(-1px);
}

.auth-toggle {
  text-align: center;
  margin-top: 24px;
  font-size: 14px;
  color: rgba(0, 0, 0, 0.6);
  line-height: 20px;
  letter-spacing: 0.1px;
  font-family: 'Roboto', sans-serif;
}

.toggle-link {
  background: none;
  border: none;
  color: #C2410C;
  font-weight: 600;
  font-size: 14px;
