  cursor: pointer;
  padding: 0;
  text-decoration: underline;
  text-underline-offset: 2px;
  -webkit-tap-highlight-color: transparent;
  transition: color 0.2s cubic-bezier(0.4, 0.0, 0.2, 1);
  font-family: 'Roboto', sans-serif;
}

.toggle-link:hover {
  color: #EA580C;
}

.toggle-link:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.success-message-container {
  text-align: center;
  padding: 40px 0;
}

.success-icon-large {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, #C2410C 0%, #EA580C 100%);
  color: #FFFFFF;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  margin: 0 auto 24px;
  font-weight: 400;
  box-shadow: 0px 1px 3px rgba(0, 0, 0, 0.3), 0px 4px 8px 3px rgba(0, 0, 0, 0.15);
}

.success-message-container h3 {
  font-size: 24px;
  font-weight: 400;
  margin-bottom: 12px;
  color: rgba(0, 0, 0, 0.87);
  letter-spacing: 0px;
  line-height: 32px;
}

.success-message-container p {
  color: rgba(0, 0, 0, 0.54);
  font-size: 14px;
  letter-spacing: 0.25px;
  line-height: 20px;
}

/* Mobile styles applied to all screens */
.welcome-header {
  padding-top: 8px;
  margin-bottom: 28px;
}

.welcome-header h2 {
  font-size: 24px;
  line-height: 32px;
}

.login-form {
  padding: calc(env(safe-area-inset-top, 0px) + 20px) 20px 28px 20px;
  padding-bottom: calc(env(safe-area-inset-bottom) + 28px);
}

.form-group {
  margin-bottom: 20px;
}
</style>
