<template>
  <div class="address-container">
    <div class="address-card">
      <div class="address-header">
        <button class="back-button" @click="goBack" aria-label="Back">
          <span class="back-icon">‹</span>
        </button>
        <div class="">
          <h1>My Delivery Details</h1>
          <p>Please provide your delivery address to continue</p>
        </div>
      </div>
      
      <form @submit.prevent="handleSubmit" class="address-form">
        <div class="form-group">
          <label for="postcode">Postcode</label>
          <input
            id="postcode"
            v-model="form.postcode"
            type="text"
            placeholder="e.g. SW1A 1AA or M1 1AA"
            required
            :disabled="loading || loadingAddresses"
            :class="['form-input', { 'input-invalid': postcodeInvalid }]"
            @input="onPostcodeChange"
          />
          <div v-if="loadingAddresses" class="loading-text">Loading addresses...</div>
          <div v-if="postcodeInvalid && form.postcode && !loadingAddresses" class="error-text">
            Please enter a valid UK postcode (e.g. SW1A 1AA or M1 1AA)
          </div>
        </div>
        
        <div class="form-group">
          <label for="address">Full Address</label>
          <input
            id="address"
            v-model="form.address"
            type="text"
            placeholder="Select an address from the list"
            required
            readonly
            :disabled="loading || loadingAddresses"
            class="form-input address-input"
            @click="showAddressModal = true"
          />
          <div v-if="!loadingAddresses && addressSuggestions.length === 0 && form.postcode && postcodeLookupAttempted" class="error-text">
            No addresses found for this postcode
          </div>
        </div>
        
        <!-- Address Selection Modal -->
        <div v-if="showAddressModal && addressSuggestions.length > 0" class="modal-overlay" @click="showAddressModal = false">
          <div class="modal-content" @click.stop>
            <div class="modal-header">
              <div class="modal-header-content">
                <div>
                  <h3>Select Address</h3>
                  <p class="modal-subtitle">Choose your address from the list</p>
                </div>
                <button class="modal-close-button" @click="showAddressModal = false" aria-label="Close">
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M18 6L6 18M6 6L18 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                  </svg>
                </button>
              </div>
            </div>
            <div class="modal-body">
              <div class="address-list">
                <button
                  v-for="(suggestion, index) in addressSuggestions"
                  :key="index"
                  class="address-option"
                  @click="selectAddress(suggestion.address)"
                >
                  <span class="address-text">{{ suggestion.address }}</span>
                  <span class="select-icon">›</span>
                </button>
              </div>
            </div>
          </div>
        </div>
        
        <div class="form-group">
          <label for="fullName">Full Name</label>
          <input
            id="fullName"
            v-model="form.fullName"
            type="text"
            placeholder="Enter your full name"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        <div class="form-group">
          <label for="mobileContact">Mobile Contact</label>
          <input
            id="mobileContact"
            v-model="form.mobileContact"
            type="tel"
            placeholder="Enter your mobile number"
            required
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        <div class="form-group">
          <label for="deliveryInstructions">Delivery Instructions</label>
          <input
            id="deliveryInstructions"
            v-model="form.deliveryInstructions"
            type="text"
            placeholder="Enter delivery instructions (optional)"
            :disabled="loading"
            class="form-input"
          />
        </div>
        
        
        <button
          type="submit"
          :disabled="loading"
          class="submit-button"
        >
          <span v-if="loading">Saving...</span>
          <span v-else>Save Address</span>
        </button>
      </form>
    </div>
  </div>
</template>

<script>
import { mapActions } from 'vuex'
import api from '@/services/api'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'Address',
  data() {
    return {
      form: {
        fullName: '',
        mobileContact: '',
        postcode: '',
        address: '',
        deliveryInstructions: ''
      },
      loading: false,
      error: null,
      addressSuggestions: [],
      loadingAddresses: false,
      postcodeLookupAttempted: false,
      postcodeDebounceTimer: null,
      postcodeInvalid: false,
      showAddressModal: false
    }
  },
  mounted() {
    this.fetchCurrentAddress()
  },
  methods: {
    ...mapActions('auth', ['saveAddress']),
    goBack() {
      this.$router.go(-1)
    },
    async fetchCurrentAddress() {
      try {
        const response = await api.get('/auth/client/address')
        const data = response.data
        
        // Pre-fill the form with current address data
        if (data.fullName) {
          this.form.fullName = String(data.fullName)
        }
        if (data.mobileContact) {
          this.form.mobileContact = String(data.mobileContact)
        }
        if (data.postcode) {
          this.form.postcode = String(data.postcode)
          // Trigger lookup if postcode exists and is valid
          this.$nextTick(async () => {
            const postcode = this.form.postcode.trim()
            if (this.isValidPostcode(postcode)) {
              await this.lookupAddresses(postcode.replace(/\s+/g, ''))
              // If we have a saved address that's not in suggestions, add it
              if (data.address && !this.addressSuggestions.find(s => s.address === data.address)) {
                this.addressSuggestions.unshift({ address: data.address })
              }
            }
          })
        }
        if (data.address) {
          this.form.address = String(data.address)
        }
        if (data.deliveryInstructions) {
          this.form.deliveryInstructions = String(data.deliveryInstructions)
        }
      } catch (error) {
        console.error('Failed to load current address:', error)
        // Don't show error if address doesn't exist yet (404), just leave form empty
        if (error.response?.status !== 404) {
          const errorMessage = error.response?.data?.message || 
                      error.message || 
                      'Failed to load current address.'
          showAlert('Load Address Failed', errorMessage)
        }
      }
    },
    async onPostcodeChange() {
      // Clear previous debounce timer
      if (this.postcodeDebounceTimer) {
        clearTimeout(this.postcodeDebounceTimer)
      }
      
      // Clear address when postcode changes
      this.form.address = ''
      this.addressSuggestions = []
      this.postcodeLookupAttempted = false
      
      // Debounce the API call - wait 500ms after user stops typing
      this.postcodeDebounceTimer = setTimeout(async () => {
        const postcode = this.form.postcode?.trim()
        
        if (!postcode || postcode.length < 3) {
          this.postcodeInvalid = false
          this.addressSuggestions = []
          this.postcodeLookupAttempted = false
          return
        }
        
        // Validate postcode before making API request
        if (this.isValidPostcode(postcode)) {
          this.postcodeInvalid = false
          await this.lookupAddresses(postcode)
          // Auto-show modal when addresses are loaded
          if (this.addressSuggestions.length > 0) {
            this.showAddressModal = true
          }
        } else {
          // Postcode is invalid, clear suggestions
          this.postcodeInvalid = true
          this.addressSuggestions = []
          this.postcodeLookupAttempted = true
        }
      }, 500)
    },
    isValidPostcode(postcode) {
      if (!postcode) return false
      
      // UK postcode regex pattern
      // Matches formats like: SW1A 1AA, M1 1AA, B33 8TH, W1A 0AX, EC1A 1BB, etc.
      // Pattern: 1-2 letters, 1-2 digits, optional space, 1 digit, 2 letters
      const ukPostcodePattern = /^[A-Z]{1,2}\d{1,2}[A-Z]?\s?\d[A-Z]{2}$/i
      
      // Remove all spaces for validation
      const cleanPostcode = postcode.replace(/\s+/g, '')
      
      // Check length (UK postcodes are 5-8 characters without spaces)
      if (cleanPostcode.length < 5 || cleanPostcode.length > 8) {
        return false
      }
      
      // Check against pattern
      return ukPostcodePattern.test(postcode)
    },
    selectAddress(address) {
      this.form.address = address
      this.showAddressModal = false
    },
    async lookupAddresses(postcode) {
      this.loadingAddresses = true
      this.postcodeLookupAttempted = true
      this.addressSuggestions = []
      
      try {
        // Remove spaces from postcode for the API call
        const cleanPostcode = postcode.replace(/\s+/g, '')
        const response = await api.get(`/auth/client/address/lookUp/${cleanPostcode}`)
        
        if (response.data && response.data.suggestions) {
          this.addressSuggestions = response.data.suggestions
        } else {
          this.addressSuggestions = []
        }
      } catch (error) {
        console.error('Failed to lookup addresses:', error)
        this.addressSuggestions = []
        // Don't show error alert for lookup failures, just show empty list
      } finally {
        this.loadingAddresses = false
      }
    },
    async handleSubmit() {
      this.loading = true
      
      try {
        await this.saveAddress({
          fullName: this.form.fullName,
          mobileContact: this.form.mobileContact,
          postcode: this.form.postcode,
          address: this.form.address,
          deliveryInstructions: this.form.deliveryInstructions
        })
        
        // Address saved successfully - return to previous page
        this.$router.go(-1)
      } catch (error) {
        const errorMessage = error.response?.data?.message || 
                    error.message || 
                    'Failed to save address. Please try again.'
        showAlert('Save Address Failed', errorMessage)
      } finally {
        this.loading = false
      }
    }
  }
}
</script>

