<template>
  <div class="dashboard">
    <div class="dashboard-header">
      <h1>Welcome to Naija Meals!</h1>
      <button @click="handleLogout" class="logout-button">Logout</button>
    </div>
    <div class="dashboard-content">
      <p>You are successfully logged in!</p>
      <p v-if="hasAddress">You have an address on file.</p>
      <p v-else>You don't have an address yet.</p>
    </div>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'

export default {
  name: 'Dashboard',
  computed: {
    ...mapGetters('auth', ['hasAddress'])
  },
  methods: {
    ...mapActions('auth', ['logout']),
    handleLogout() {
      this.logout()
      this.$router.push('/login')
    }
  }
}
</script>

<style scoped>
.dashboard {
  min-height: 100vh;
  padding: 40px;
  background: #ffffff;
  max-width: 1200px;
  margin: 0 auto;
}

.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 40px;
  padding-bottom: 20px;
  border-bottom: 2px solid #e0e0e0;
}

.dashboard-header h1 {
  color: #C2410C;
  font-size: 32px;
}

.logout-button {
  padding: 10px 20px;
  background: #dc3545;
  color: white;
  border: none;
  border-radius: 0;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
  transition: all 0.3s ease;
}

.logout-button:hover {
  background: #c82333;
  transform: translateY(-2px);
}

.dashboard-content {
  font-size: 18px;
  color: #1a202c;
  line-height: 1.8;
}
</style>
