import Vue from 'vue'
import VueRouter from 'vue-router'
import Login from '../views/Login.vue'
import Dashboard from '../views/Dashboard.vue'
import Address from '../views/Address.vue'
import Restaurants from '../views/Restaurants.vue'
import RestaurantMenu from '../views/RestaurantMenu.vue'
import Cart from '../views/Cart.vue'
import Payment from '../views/Payment.vue'
import PaymentSuccess from '../views/PaymentSuccess.vue'
import Orders from '../views/Orders.vue'
import OrderTracking from '../views/OrderTracking.vue'
import ForgotPassword from '../views/ForgotPassword.vue'
import ContactUs from '../views/ContactUs.vue'
import TermsAndConditions from '../views/TermsAndConditions.vue'
import PartnerWithUs from '../views/PartnerWithUs.vue'
import BecomeACourier from '../views/BecomeACourier.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: () => {
      const token = localStorage.getItem('token')
      const hasAddress = localStorage.getItem('hasAddress') === 'true'
      if (token) {
        if (hasAddress) {
          return { name: 'RestaurantsRoute' }
        } else {
          return { name: 'Address' }
        }
      } else {
        return { name: 'Login' }
      }
    }
  },
  {
    path: '/login',
    name: 'Login',
    component: Login
  },
  {
    path: '/forgot-password',
    name: 'ForgotPassword',
    component: ForgotPassword
  },
  {
    path: '/address',
    name: 'Address',
    component: Address,
    meta: { requiresAuth: true }
  },
  {
    path: '/restaurants',
    name: 'RestaurantsRoute',
    component: Restaurants
  },
  {
    path: '/restaurant/:id',
    name: 'RestaurantMenu',
    component: RestaurantMenu,
    meta: { requiresAuth: true }
  },
  {
    path: '/cart',
    name: 'Cart',
    component: Cart,
    meta: { requiresAuth: true }
  },
  {
    path: '/payment',
    name: 'Payment',
    component: Payment,
    meta: { requiresAuth: true }
  },
  {
    path: '/payment/success/:orderId',
    name: 'PaymentSuccess',
    component: PaymentSuccess,
    meta: { requiresAuth: true }
  },
  {
    path: '/dashboard',
    name: 'Dashboard',
    component: Dashboard,
    meta: { requiresAuth: true }
  },
  {
    path: '/orders',
    name: 'Orders',
    component: Orders,
    meta: { requiresAuth: true }
  },
  {
    path: '/order/tracking/:orderId',
    name: 'OrderTracking',
    component: OrderTracking,
    meta: { requiresAuth: true }
  },
  {
    path: '/contact-us',
    name: 'ContactUs',
    component: ContactUs,
    meta: { requiresAuth: true }
  },
  {
    path: '/terms-and-conditions',
    name: 'TermsAndConditions',
    component: TermsAndConditions
  },
  {
    path: '/partner-with-us',
    name: 'PartnerWithUs',
    component: PartnerWithUs
  },
  {
    path: '/become-a-courier',
    name: 'BecomeACourier',
    component: BecomeACourier
  }
]

const router = new VueRouter({
  mode: 'hash',
  base: process.env.BASE_URL,
  routes
})

// Navigation guard to check authentication
router.beforeEach((to, from, next) => {
  const token = localStorage.getItem('token')
  const hasAddress = localStorage.getItem('hasAddress') === 'true'
  
    // Prevent going back to payment page after payment is completed
    // If trying to access payment page with clientSecret and orderId and coming from PaymentSuccess,
    // redirect to restaurants page to prevent back navigation
    if (to.name === 'Payment' && to.query.clientSecret && to.query.orderId && from.name === 'PaymentSuccess') {
      next({ name: 'RestaurantsRoute', replace: true })
      return
    }
  
  // If user has a token and tries to access login or password reset page, redirect them
  if (token && (to.name === 'Login' || to.name === 'ForgotPassword')) {
    // Redirect based on whether they have an address
    if (hasAddress) {
      next({ name: 'RestaurantsRoute', replace: true })
    } else {
      next({ name: 'Address', replace: true })
    }
    return
  }
  
  // If user is not logged in and trying to access protected routes
  if (!token && to.name !== 'Login' && to.name !== 'ForgotPassword' && to.name !== 'Restaurants' && to.name !== 'RestaurantsRoute' && to.name !== 'TermsAndConditions' && to.name !== 'PartnerWithUs' && to.name !== 'BecomeACourier') {
    next({ name: 'Login' })
    return
  }
  
  // Redirect unauthenticated users trying to access restaurants to login
  if (!token && (to.name === 'Restaurants' || to.name === 'RestaurantsRoute')) {
    next({ name: 'Login' })
    return
  } 
  // If user is logged in but doesn't have address and trying to access protected pages
  else if (token && !hasAddress && (to.name === 'Dashboard' || to.name === 'Restaurants' || to.name === 'RestaurantsRoute')) {
    next({ name: 'Address' })
  }
  else {
    next()
  }
})


export default router
