<template>
  <div class="cart-container">
    <div class="cart-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>Cart</h1>
        <p v-if="cartItems.length > 0">{{ cartItemCount }} item{{ cartItemCount !== 1 ? 's' : '' }}</p>
      </div>
    </div>
    
    <div v-if="cartItems.length === 0" class="empty-cart">
      <div class="empty-icon">🛒</div>
      <h2>Your cart is empty</h2>
      <p>Add items from the menu to get started</p>
      <button @click="goBack" class="browse-button">Browse Restaurants</button>
    </div>
    
    <div v-else class="cart-content">
      <div class="cart-items">
        <div
          v-for="item in cartItems"
          :key="item.id"
          class="cart-item"
        >
          <div class="item-image-container">
            <img
              :src="item.image"
              :alt="item.name"
              class="item-image"
              @error="handleImageError"
            />
          </div>
          
          <div class="item-details">
            <div class="item-header-row">
              <div class="item-text-container">
                <h3 class="item-name">{{ item.name }}</h3>
                <p v-if="item.description" class="item-description">{{ item.description }}</p>
              </div>
              <button
                class="remove-button"
                @click="removeItem(item.id)"
                aria-label="Remove item"
              >
                ×
              </button>
            </div>
            
            <div class="item-bottom-row">
              <div class="item-price">£{{ (item.price * item.quantity).toFixed(2) }}</div>
              <div class="quantity-controls">
                <button
                  type="button"
                  class="quantity-button"
                  @click.stop="decreaseQuantity(item.id)"
                  aria-label="Decrease quantity"
                >
                  −
                </button>
                <span class="quantity-value">{{ item.quantity }}</span>
                <button
                  type="button"
                  class="quantity-button"
                  @click.stop="increaseQuantity(item.id)"
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      
      <div class="cart-footer">
        <div class="cart-summary">
          <div class="summary-row">
            <span class="summary-label">Order Price</span>
            <span class="summary-value">£{{ cartSubtotal.toFixed(2) }}</span>
          </div>
          <div class="summary-row">
            <span class="summary-label">Delivery Fee</span>
            <span class="summary-value">
              <span v-if="loadingFee">...</span>
              <span v-else>£{{ deliveryFee.toFixed(2) }}</span>
            </span>
          </div>
          <div class="summary-row">
            <span class="summary-label">Service Fee</span>
            <span class="summary-value">£{{ serviceFee.toFixed(2) }}</span>
          </div>
          <div class="summary-row total-row">
            <span class="summary-label">Total</span>
            <span class="summary-value">
              <span v-if="loadingFee">...</span>
              <span v-else>£{{ cartTotal.toFixed(2) }}</span>
            </span>
          </div>
        </div>

        <button class="checkout-button" @click="confirmAction" :disabled="processingCheckout">
          <span v-if="processingCheckout">Processing...</span>
          <span v-else>Proceed to Checkout</span>
        </button>

        
<!--        <button class="checkout-button" @click="checkout" :disabled="processingCheckout">-->
<!--          <span v-if="processingCheckout">Processing...</span>-->
<!--          <span v-else>Proceed to Checkout</span>-->
<!--        </button>-->
      </div>
    </div>

    <!-- Custom Confirm Modal -->
    <transition name="modal">
      <div v-if="showConfirmModal" class="modal-overlay" @click="closeConfirmModal">
        <div class="modal-content" @click.stop>
          <div class="modal-header">
            <div class="modal-header-content">
              <div>
                <h3>Delivery Address</h3>
                <p class="modal-subtitle">Confirm your delivery address</p>
              </div>
              <button class="modal-close-button" @click="closeConfirmModal" aria-label="Close">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M18 6L6 18M6 6L18 18" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </button>
            </div>
          </div>
          <div class="modal-body">
            <div class="address-display">
              <div class="address-icon">📍</div>
              <p class="address-text">{{ deliveryAddress }}</p>
            </div>
          </div>
          <div class="modal-footer">
            <button class="modal-button modal-button-secondary" @click="onCancel">
              Change Address
            </button>
            <button class="modal-button modal-button-primary" @click="onContinue">
              Continue
            </button>
          </div>
        </div>
      </div>
    </transition>
