<script>
import { mapGetters, mapActions } from 'vuex'
import api from '@/services/api'
import { showAlert, showConfirmDialog, vibrate } from '@/utils/webUtils'

export default {
  name: 'Cart',
  data() {
    return {
      deliveryAddress: '',
      loadingFee: false,
      processingCheckout: false,
      showConfirmModal: false
    }
  },
  mounted() {
    this.fetchDeliveryFee();
    this.fetchDeliveryAddress();
    window.onConfirmContinue = this.onContinue;
    window.onConfirmCancel = this.onCancel;
  },
  beforeDestroy() {
    delete window.onConfirmContinue
    delete window.onConfirmCancel
  },
  computed: {
    ...mapGetters('cart', ['cartItems', 'cartItemCount', 'cartSubtotal', 'deliveryFee', 'serviceFee', 'cartTotal'])
  },
  methods: {
    ...mapActions('cart', ['updateQuantity', 'removeFromCart', 'fetchDeliveryFee']),
    async fetchDeliveryFee() {
      this.loadingFee = true
      try {
        await this.$store.dispatch('cart/fetchDeliveryFee')
      } catch (error) {
        console.error('Failed to load delivery fee:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Failed to load delivery fee. Please try again.'
        showAlert('Load Delivery Fee Failed', errorMessage)
      } finally {
        this.loadingFee = false
      }
    },
    async fetchDeliveryAddress() {
      try {
        const response = await api.get('/auth/client/address')
        const data = response.data
        
        // Format the address from the API response
        const addressParts = []

        if (data.address) {
          addressParts.push(data.address)
        }

        this.deliveryAddress = addressParts.join(",") || 'No address available'
      } catch (error) {
        console.error('Failed to load delivery address:', error)
        this.deliveryAddress = 'No address available'
      }
    },
    confirmAction() {
      this.showConfirmModal = true
    },
    closeConfirmModal() {
      this.showConfirmModal = false
    },
    onContinue() {
      this.showConfirmModal = false
      this.checkout()
    },
    onCancel() {
      this.showConfirmModal = false
      this.$router.push('/address')
    },
    goBack() {
      this.$router.go(-1)
    },
    increaseQuantity(itemId) {
      vibrate(8);
      const item = this.cartItems.find(i => i.id === itemId)
      if (item) {
        this.updateQuantity({ itemId, quantity: item.quantity + 1 })
      }
    },
    decreaseQuantity(itemId) {
      vibrate(8);
      const item = this.cartItems.find(i => i.id === itemId)
      if (item) {
        this.updateQuantity({ itemId, quantity: item.quantity - 1 })
      }
    },
    removeItem(itemId) {
      vibrate(8);
      this.removeFromCart(itemId)
    },
    async checkout() {
      if (this.processingCheckout) return
      
      this.processingCheckout = true
      
      try {
        // Format cart items for the API
        const items = this.cartItems.map(item => ({
          item_id: item.id,
          quantity: item.quantity
        }))
        
        // Make POST request to complete order
        const response = await api.post('/api/client/restaurant/complete', items)
        
        const { clientSecret, orderId } = response.data
        
        if (!clientSecret || !orderId) {
          throw new Error('Invalid response from server')
        }
        
        // Navigate to payment page with clientSecret and orderId
        this.$router.push({
          name: 'Payment',
          query: {
            clientSecret,
            orderId,
            totalAmount: this.cartTotal
          }
        })
      } catch (error) {
        console.error('Checkout error:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Failed to proceed to checkout. Please try again.'
        showAlert('Checkout Failed', errorMessage)
        this.processingCheckout = false
      }
    },
    handleImageError(event) {
      event.target.src = 'https://naijameals.com/img/coming_soon.jpg'
    }
  }
}
</script>

