<template>
  <div class="orders-container">
    <div class="orders-header">
      <button class="back-button" @click="goBack" aria-label="Back">
        <span class="back-icon">‹</span>
      </button>
      <div class="header-content">
        <h1>My Orders</h1>
        <p v-if="orders.length > 0">{{ orders.length }} order{{ orders.length !== 1 ? 's' : '' }}</p>
      </div>
    </div>
    
    <div v-if="loading" class="loading-container">
      <div class="loading-spinner"></div>
      <p>Loading orders...</p>
    </div>
    
    <div v-else-if="orders.length === 0" class="empty-orders">
      <div class="empty-icon">📦</div>
      <h2>No orders yet</h2>
      <p>Your past orders will appear here</p>
      <button @click="goBack" class="browse-button">Browse Restaurants</button>
    </div>
    
    <div v-else class="orders-content">
      <div class="orders-list">
        <div
          v-for="order in orders"
          :key="order.orderNumber"
          class="order-card"
        >
          <div class="order-header" @click.stop="toggleOrder(order.orderNumber)">
            <div class="order-info">
              <h3 class="order-number">Order #{{ order.orderNumber }}</h3>
              <p class="restaurant-name"> {{ order.restaurant }}</p>
              <p class="order-date">{{ formatDate(order.orderDate) }}</p>
              <p v-if="!isExpanded(order.orderNumber)" class="order-summary-text">
                {{ order.orderItems.length }} item{{ order.orderItems.length !== 1 ? 's' : '' }} • £{{ order.totalPrice.toFixed(2) }}
              </p>
            </div>
            <div class="order-header-right">
              <div v-if="isExpanded(order.orderNumber)" class="order-total">
                <span class="total-label">Total</span>
                <span class="total-value">£{{ order.totalPrice.toFixed(2) }}</span>
              </div>
              <div class="expand-icon" :class="{ 'expanded': isExpanded(order.orderNumber) }">
                <span>›</span>
              </div>
            </div>
          </div>
          
          <div v-show="isExpanded(order.orderNumber)" class="order-details">
            <div class="order-items">
              <div
                v-for="item in order.orderItems"
                :key="item.itemId"
                class="order-item"
              >
                <div class="item-image-container">
                  <img
                    :src="item.itemImage"
                    :alt="item.itemName"
                    class="item-image"
                    @error="handleImageError"
                  />
                </div>
                
                <div class="item-details">
                  <h4 class="item-name">{{ item.itemName }}</h4>
                  <div class="item-meta">
                    <span class="item-quantity">Qty: {{ item.quantity }}</span>
                    <span class="item-price">£{{ item.itemPrice }}</span>
                  </div>
                </div>
                
                <div class="item-total">
                  £{{ item.price.toFixed(2) }}
                </div>
              </div>
            </div>
            
            <div class="order-summary">
              <div class="summary-row">
                <span class="summary-label">Order Price</span>
                <span class="summary-value">£{{ order.restaurantPrice.toFixed(2) }}</span>
              </div>
              <div class="summary-row">
                <span class="summary-label">Service Charge</span>
                <span class="summary-value">£{{ order.serviceCharge.toFixed(2) }}</span>
              </div>
              <div class="summary-row">
                <span class="summary-label">Delivery Fee</span>
                <span class="summary-value">£{{ order.deliveryPrice.toFixed(2) }}</span>
              </div>
              <div class="summary-row total-row">
                <span class="summary-label">Total</span>
                <span class="summary-value">£{{ order.totalPrice.toFixed(2) }}</span>
              </div>

              <button  @click="goToTracking(order.orderNumber)" class="continue-button">Track My Order </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import api from '@/services/api'
import { showAlert } from '@/utils/webUtils'

export default {
  name: 'Orders',
  data() {
    return {
      orders: [],
      loading: false,
      expandedOrders: {}
    }
  },
  mounted() {
    this.loadOrders()
  },
  methods: {
    goToTracking(orderId) {
      this.$router.push({
        name: 'OrderTracking',
        params: { orderId: orderId }
      })
    },
    async loadOrders() {
      this.loading = true
      try {
        const response = await api.get('/auth/client/orders')
        this.orders = response.data || []
      } catch (error) {
        console.error('Failed to load orders:', error)
        const errorMessage = error.response?.data?.message || error.message || 'Failed to load orders. Please try again.'
        showAlert('Load Orders Failed', errorMessage)
      } finally {
        this.loading = false
      }
    },
    formatDate(dateString) {
      const date = new Date(dateString)
      return date.toLocaleDateString('en-GB', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    },
    goBack() {
      this.$router.go(-1)
    },
    toggleOrder(orderNumber) {
      const currentState = this.expandedOrders[orderNumber] || false
      this.$set(this.expandedOrders, orderNumber, !currentState)
    },
    isExpanded(orderNumber) {
      return this.expandedOrders[orderNumber] === true
    },
    handleImageError(event) {
      event.target.src = 'https://naijameals.com/img/coming_soon.jpg'
    }
  }
}
</script>

